/* Dados operacionais não pertencem ao pacote público. Aparelhos existentes
   continuam lendo seu armazenamento local; aparelhos novos recebem quadras,
   culturas e estudos somente depois da leitura autenticada do workspace. */
var DD={};

/* ============ DATE / STAGE UTILS ============ */
function pD(d){
  if(!d)return null;
  var s=String(d).trim();
  var m=s.match(/(\d{1,2})\s*\/\s*(\d{1,2})\s*\/\s*(\d{4})/);
  if(m)return new Date(+m[3],+m[2]-1,+m[1]);
  m=s.match(/(\d{4})-(\d{2})-(\d{2})/);
  return m?new Date(+m[1],+m[2]-1,+m[3]):null;
}
function fD(d){
  if(!d)return "";
  var dd=String(d.getDate()).padStart(2,'0');
  var mm=String(d.getMonth()+1).padStart(2,'0');
  return dd+"/"+mm+"/"+d.getFullYear();
}
function fDIso(d){
  if(!d)return "";
  var dd=String(d.getDate()).padStart(2,'0');
  var mm=String(d.getMonth()+1).padStart(2,'0');
  return d.getFullYear()+"-"+mm+"-"+dd;
}
function isoToBR(iso){
  if(!iso)return "";
  var m=String(iso).match(/(\d{4})-(\d{2})-(\d{2})/);
  return m?m[3]+"/"+m[2]+"/"+m[1]:iso;
}
function brToIso(br){
  if(!br)return "";
  var m=String(br).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if(!m)return "";
  return m[3]+"-"+String(m[2]).padStart(2,'0')+"-"+String(m[1]).padStart(2,'0');
}
/* O registro agronômico usa o fuso da operação, não o fuso acidental do
   navegador. Isso importa em auditorias abertas em outro país, em máquinas
   virtuais e perto da meia-noite: o mesmo evento não pode trocar de dia só
   porque foi consultado em outro aparelho. O instante continua armazenado em
   UTC (ISO/epoch); estas funções cuidam apenas da data/hora civil exibida. */
var AGRACTA_TIME_ZONE='America/Sao_Paulo';
function _agDateParts(value){
  var d=value instanceof Date?value:new Date(value==null?Date.now():value), out={};
  if(isNaN(d))return null;
  try{
    new Intl.DateTimeFormat('en-CA',{timeZone:AGRACTA_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(d).forEach(function(p){if(p.type!=='literal')out[p.type]=p.value;});
    return out;
  }catch(e){
    return {year:String(d.getFullYear()),month:String(d.getMonth()+1).padStart(2,'0'),day:String(d.getDate()).padStart(2,'0'),hour:String(d.getHours()).padStart(2,'0'),minute:String(d.getMinutes()).padStart(2,'0'),second:String(d.getSeconds()).padStart(2,'0')};
  }
}
function _agFormatDateTime(value,opts){
  var d=value instanceof Date?value:new Date(value); if(isNaN(d))return '';
  var o=opts?Object.assign({},opts):{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'};
  try{o.timeZone=AGRACTA_TIME_ZONE;return new Intl.DateTimeFormat('pt-BR',o).format(d);}catch(e){return d.toLocaleString('pt-BR',o);}
}
function _agNowHHMM(){var p=_agDateParts(Date.now());return p?(p.hour+':'+p.minute):'';}
/* Converte uma data/hora civil do estudo para epoch no fuso operacional. A
   iteração também lida corretamente com mudanças históricas de offset. */
function _agLocalEpoch(iso,hhmm){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(String(iso||''))||!/^\d{2}:\d{2}$/.test(String(hhmm||'')))return NaN;
  var a=String(iso).split('-'),h=String(hhmm).split(':'),target=Date.UTC(+a[0],+a[1]-1,+a[2],+h[0],+h[1],0),guess=target;
  for(var i=0;i<3;i++){var p=_agDateParts(guess);if(!p)break;var shown=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second);guess+=target-shown;}
  return guess;
}
function today0(){return pD(todayISO())}
function daysBetween(a,b){return Math.round((b-a)/864e5)}

/* ===== MOMENTO DA AVALIAÇÃO — HAT/DAT explícito, OPCIONAL ====================
   O app sempre derivou o momento da DATA (daysBetween → DAA). Isso basta para
   ensaio de campo, mas não para bioensaio: um knockdown lê a 1, 2, 4 e 24 horas
   DO MESMO DIA, e pela data as quatro leituras são o mesmo ponto — três eram
   descartadas sem avisar.

   Agora a avaliação PODE declarar `momento:{valor, unidade:'HAT'|'DAT'}`. Quando
   declara, é ele que manda no eixo do tempo; quando não declara — que é o caso
   de tudo que já existe — nada muda: continua o DAA derivado da data.

   `dias` é sempre em DIAS (HAT vira fração) porque a AACPD integra por trapézio
   sobre esse eixo; misturar hora com dia ali daria área errada. */
function avMomento(av, daaDerivado){
  var m=av&&av.momento, v=m?parseFloat(String(m.valor).replace(',','.')):NaN;
  var u=m&&(m.unidade==='HAT'||m.unidade==='DAT')?m.unidade:null;
  if(u && isFinite(v)){
    var dias=(u==='HAT')?(v/24):v;
    return { dias:dias, chave:u+':'+v, rotulo:_fmtMom(v)+' '+u, unidade:u, valor:v, explicito:true };
  }
  var d=(daaDerivado==null?0:daaDerivado);
  return { dias:d, chave:'DAA:'+d, rotulo:d+' DAA', unidade:'DAA', valor:d, explicito:false };
}
function _fmtMom(v){ return (Math.round(v*100)/100).toString().replace('.',','); }
function addDays(d,n){var x=new Date(d);x.setDate(x.getDate()+n);return x}

function cDAP(p){var d=pD(p);return d&&!isNaN(d)?Math.floor((today0()-d)/864e5):null}
function gS(c,dap){
  if(dap===null)return{s:"\u2014",l:"Sem data",c:"#616161"};
  if(dap<0)return{s:"PLAN",l:"Plantio em "+Math.abs(dap)+"d",c:"#42a5f5"};
  var t=FEN[c]||FEN._;
  for(var i=0;i<t.length;i++){if(dap<=t[i].m)return t[i]}
  return t[t.length-1];
}
function gC(c){return CC[c]||CC._}
function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}
function uid(){ try{ if(window.crypto&&crypto.randomUUID) return 's'+crypto.randomUUID(); }catch(e){} return 's'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)+Math.random().toString(36).slice(2,6); }
