  if(!force){ try{ var _aberto=false; _notesLayer.eachLayer(function(l){ if(l.isPopupOpen && l.isPopupOpen()) _aberto=true; }); if(_aberto) return; }catch(e){} }
  _notesLayer.clearLayers();
  
