function saveAdminSettings(){
  if(!isAdmin() && !window._adminUnlocked){ alert('Para mudar as configurações de admin, destrave o Painel com a senha de administrador.'); return; }
  var email = (document.getElementById('admEmail')||{}).value.trim();
  var pass = (document.getElementById('admPass')||{}).value;
  if(!email || !pass){ alert('Preencha o e-mail e a senha.'); return; }
  
  ensureConfig();
  data.__config.adminEmail = email.toLowerCase();
  if(pass.length === 64 && /^[0-9a-f]{64}$/i.test(pass)) {
    data.__config.adminPassword = pass.toLowerCase();
  } else {
    data.__config.adminPassword = sha256(pass);
  }
  save(); if(typeof cloudSave==='function'){ try{ cloudSave(); }catch(e){} }
  if(typeof dbUpsertConfig==='function') dbUpsertConfig(); /* Etapa 3 */
  _stxToast('Configurações salvas — aguarde "salvo na nuvem".');
  renderAdminDashboard();
}

/* ===== Contas de técnico: Firebase Auth + roster de membros ===== */
function _genSenhaTec(){ var cs='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789',s=''; for(var i=0;i<10;i++)s+=cs.charAt(Math.floor(Math.random()*cs.length)); return s; }
function adminGenSenha(){ var i=document.getElementById('addUsrSenha'); if(i){ i.value=_genSenhaTec(); i.focus(); } }
function _adminMsg(t,erro){ var e=document.getElementById('addUsrMsg'); if(e){ e.textContent=t||''; e.style.color=erro?'#ff8a8a':'#37d684'; } }
function _copiarCreds(){ var ac=window._ultimoAcessoCriado; if(!ac)return; var t='Agracta — acesso\nSite: https://www.agracta.com.br\nE-mail: '+ac.email+'\nSenha: '+ac.senha;
  function done(){ if(typeof _stxToast==='function')_stxToast('Credenciais copiadas'); }
  try{ if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(done,function(){ window.prompt('Copie as credenciais:', t); }); } else { window.prompt('Copie as credenciais:', t); } }catch(e){ window.prompt('Copie as credenciais:', t); } }

/* Chama a Edge Function 'criar-tecnico' (cria conta OU redefine senha). Segredo fica no servidor. */
function _invocarCriarTecnico(email, nome, senha, isReset){
  if(!cloudInit()||!SB||!SB.functions){ _adminMsg('Sem conexão com o servidor.',true); return; }
  var btn=document.getElementById('addUsrBtn'); if(btn && !isReset){ btn.disabled=true; btn.textContent='Criando…'; }
  if(!isReset) _adminMsg('Criando acesso…',false);
  SB.functions.invoke('criar-tecnico',{ body:{ email:email, nome:nome, senha:senha } }).then(function(res){
    if(btn && !isReset){ btn.disabled=false; btn.textContent='Criar acesso do técnico'; }
    var d=res&&res.data, er=res&&res.error;
    if(er || !d || d.error){
      var msg=(d&&d.error) || (er&&er.message) || 'Falha ao criar acesso.';
      if(/not found|404|Failed to send|fetch|non-2xx|Edge Function|FunctionsFetchError|FunctionsRelayError/i.test(String(msg))){
        msg='A função "criar-tecnico" ainda não foi publicada no Supabase. (Me avise que te passo o passo de 2 min.)';
      }
      _adminMsg(msg,true); if(isReset && typeof _stxToast==='function')_stxToast(msg); return;
    }
    window._ultimoAcessoCriado={ email:d.email||email, senha:d.senha||senha, criado:!!d.criado };
    /* espelha no roster BPL local (allowedUsers) por continuidade do registro */
    try{ ensureConfig(); var arr=data.__config.allowedUsers||(data.__config.allowedUsers=[]);
      var f=arr.find(function(u){return u&&u.email&&u.email.toLowerCase().trim()===(email||'').toLowerCase().trim();});
      if(f){ if(nome)f.nome=nome; } else { arr.push({email:email,nome:nome,addedAt:Date.now()}); }
      if(data.__config.delUsers) delete data.__config.delUsers[(email||'').toLowerCase().trim()];
      save(); if(typeof cloudSave==='function'){try{cloudSave();}catch(_e){}} }catch(_e){}
    renderAdminDashboard();
  }, function(err){ if(btn&&!isReset){btn.disabled=false;btn.textContent='Criar acesso do técnico';} _adminMsg('Falha de conexão: '+((err&&err.message)||err),true); });
}
function criarAcessoTecnico(){
  if(!isAdmin() && !window._adminUnlocked){ alert('Destrave o Painel com a senha de administrador.'); return; }
  var email=((document.getElementById('addUsrEmail')||{}).value||'').trim().toLowerCase();
  var nome=((document.getElementById('addUsrNome')||{}).value||'').trim();
  var senha=((document.getElementById('addUsrSenha')||{}).value||'').trim();
  if(!email||!nome){ _adminMsg('Preencha o e-mail e o nome do técnico.',true); return; }
  if(senha && senha.length<6){ _adminMsg('A senha precisa de pelo menos 6 caracteres (ou deixe vazio para gerar).',true); return; }
  _invocarCriarTecnico(email, nome, senha, false);
}

/* Lista as CONTAS reais (perfis) — fonte da verdade de quem tem acesso + nome p/ auditoria.
   Status de acesso (ativo/desativado) vem do Auth via a função remover-tecnico (best-effort). */
function _carregarPerfis(){
  var box=document.getElementById('admPerfisList'); if(!box) return;
  if(!cloudInit()||!SB){ box.innerHTML='<div style="color:#ff8a8a;font-size:12px;text-align:center;padding:8px">Sem conexão.</div>'; return; }
  SB.from('perfis').select('user_id,email,nome,papel').then(function(res){
    if(res.error){ box.innerHTML='<div style="color:#ff8a8a;font-size:12px;text-align:center;padding:8px">Não foi possível ler as contas: '+esc(res.error.message)+'</div>'; return; }
    var arr=(res.data||[]).slice().sort(function(a,b){ if(a.papel!==b.papel) return a.papel==='admin'?-1:1; return (a.email||'').localeCompare(b.email||''); });
    window._perfisCache=arr;
    if(!arr.length){ box.innerHTML='<div style="color:#8aa88a;font-size:12px;text-align:center;padding:8px">Nenhuma conta ainda. Crie a primeira abaixo.</div>'; return; }
    var done=function(set){ window._disabledSet=set||{}; _renderPerfisList(arr, window._disabledSet); };
    try{
      SB.functions.invoke('remover-tecnico',{body:{action:'status'}}).then(function(r){
        var set={}; if(r&&r.data&&Array.isArray(r.data.disabled)){ r.data.disabled.forEach(function(e){ set[(e||'').toLowerCase()]=1; }); }
        done(set);
      }, function(){ done({}); });
    }catch(e){ done({}); }
  }, function(){ box.innerHTML='<div style="color:#ff8a8a;font-size:12px;text-align:center;padding:8px">Falha de conexão ao ler contas.</div>'; });
}
function _renderPerfisList(arr, disabledSet){
  var box=document.getElementById('admPerfisList'); if(!box) return;
  box.innerHTML=arr.map(function(p,i){
    var isAdm=p.papel==='admin';
    var off=!isAdm && !!disabledSet[(p.email||'').toLowerCase()];
    var badge='<span style="font-size:9px;font-weight:800;letter-spacing:.5px;padding:2px 6px;border-radius:6px;'+(isAdm?'background:#3a2a0c;color:#ffce5a;border:1px solid #6b531b':'background:#0f2a1a;color:#37d684;border:1px solid #245a36')+'">'+(isAdm?'ADMIN':'TÉCNICO')+'</span>';
    var offBadge= off?'<span style="font-size:9px;font-weight:800;letter-spacing:.5px;padding:2px 6px;border-radius:6px;background:#3a1212;color:#ff9a8a;border:1px solid #6b1f1f;margin-right:6px">DESATIVADO</span>':'';
    return '<div style="border-bottom:1px solid #1f2c22;padding:8px 0;'+(off?'opacity:.7':'')+'">'+
      '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><div style="font-size:12px;color:#cfe0d4;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(p.email)+'</div><div style="white-space:nowrap">'+offBadge+badge+'</div></div>'+
      '<div style="display:flex;gap:6px;margin-top:6px">'+
        '<input id="pf_'+i+'" class="delpwd-inp" style="padding:7px;font-size:12px;flex:1" type="text" value="'+esc(p.nome||'')+'" placeholder="Nome completo (auditoria)">'+
        '<button onclick="salvarNomePerfil('+i+')" style="background:#1f5a2a;color:#eafaea;border:none;border-radius:7px;padding:0 12px;font-size:12px;font-weight:700;cursor:pointer">Salvar nome</button>'+
      '</div>'+
      (isAdm?'':'<div style="display:flex;gap:14px;margin-top:6px"><button onclick="redefinirSenhaTecnico('+i+')" style="background:transparent;color:#8a9f90;border:none;padding:0;font-size:10px;cursor:pointer;text-decoration:underline">redefinir senha</button>'+
        '<button onclick="alternarAcessoTecnico('+i+','+(off?'true':'false')+')" style="background:transparent;color:'+(off?'#37d684':'#ff9a8a')+';border:none;padding:0;font-size:10px;cursor:pointer;text-decoration:underline">'+(off?'reativar acesso':'desativar acesso')+'</button></div>')+
    '</div>';
  }).join('');
}
/* Desativa (bane, mantém histórico) ou reativa o acesso — via função remover-tecnico (servidor) */
function alternarAcessoTecnico(i, isOff){
  var p=(window._perfisCache||[])[i]; if(!p) return;
  var acao=isOff?'enable':'disable';
  if(!confirm((isOff?'REATIVAR':'DESATIVAR')+' o acesso de '+(p.nome||p.email)+'?\n\n'+(isOff?'Ele volta a conseguir entrar no app.':'Ele NÃO consegue mais entrar (a conta e todo o histórico são mantidos).'))) return;
  if(!cloudInit()||!SB||!SB.functions){ if(typeof _stxToast==='function')_stxToast('Sem conexão.'); return; }
  if(typeof _stxToast==='function')_stxToast(isOff?'Reativando…':'Desativando…');
  SB.functions.invoke('remover-tecnico',{body:{email:p.email, action:acao}}).then(function(res){
    var d=res&&res.data, er=res&&res.error;
    if(er || !d || d.error){
      var msg=(d&&d.error)||(er&&er.message)||'Falha.';
      if(/not found|404|Failed to send|FunctionsFetchError|FunctionsRelayError|non-2xx/i.test(String(msg))) msg='A função "remover-tecnico" ainda não foi publicada no Supabase.';
      if(typeof _stxToast==='function')_stxToast(msg); return;
    }
    if(typeof _stxToast==='function')_stxToast(isOff?'Acesso reativado':'Acesso desativado');
    _carregarPerfis();
  }, function(){ if(typeof _stxToast==='function')_stxToast('Falha de conexão.'); });
}
/* Salva o NOME no perfil (RLS permite admin) — sem mexer na senha, sem republicar nada */
function salvarNomePerfil(i){
  var p=(window._perfisCache||[])[i]; if(!p||!SB) return;
  var inp=document.getElementById('pf_'+i); var nome=inp?inp.value.trim():'';
  if(inp) inp.disabled=true;
  SB.from('perfis').update({nome:nome}).eq('user_id',p.user_id).then(function(res){
    if(inp) inp.disabled=false;
    if(res.error){ if(typeof _stxToast==='function')_stxToast('Erro ao salvar nome: '+res.error.message); return; }
    p.nome=nome;
    try{ ensureConfig(); var arr=data.__config.allowedUsers||(data.__config.allowedUsers=[]);
      var f=arr.find(function(u){return u&&u.email&&u.email.toLowerCase().trim()===(p.email||'').toLowerCase().trim();});
      if(f){ f.nome=nome; } else { arr.push({email:p.email,nome:nome,addedAt:Date.now()}); }
      save(); if(typeof cloudSave==='function'){try{cloudSave();}catch(_e){}} }catch(_e){}
    if(typeof _stxToast==='function') _stxToast('Nome salvo: '+(nome||'(vazio)'));
  }, function(){ if(inp) inp.disabled=false; if(typeof _stxToast==='function')_stxToast('Falha de conexão.'); });
}
/* Gera nova senha p/ um técnico existente (mostra para repassar) */
function redefinirSenhaTecnico(i){
  var p=(window._perfisCache||[])[i]; if(!p) return;
  if(!confirm('Redefinir a senha de '+(p.nome||p.email)+'?\nSerá gerada uma senha nova para você repassar.')) return;
  var inp=document.getElementById('pf_'+i); var nome=inp?inp.value.trim():(p.nome||'');
  _invocarCriarTecnico(p.email, nome, '', true);
}

function addAllowedUser(){
  if(!isAdmin() && !window._adminUnlocked){ alert('Para autorizar técnicos, destrave o Painel com a senha de administrador.'); return; }
  var email = (document.getElementById('addUsrEmail')||{}).value.trim();
  var nome = (document.getElementById('addUsrNome')||{}).value.trim();
  if(!email || !nome){ alert('Preencha o e-mail e o nome do técnico.'); return; }
  
  ensureConfig();
  var exists = data.__config.allowedUsers.some(function(u){
    return u && typeof u.email === 'string' && u.email.toLowerCase().trim() === email.toLowerCase().trim();
  });
  if(exists){ alert('Este e-mail já está autorizado.'); return; }
  
  try{ if(data.__config.delUsers) delete data.__config.delUsers[email.toLowerCase().trim()]; }catch(e){} /* re-adicionar: limpa lápide antiga */
  data.__config.allowedUsers.push({ email: email, nome: nome, addedAt: Date.now() });
  save(); if(typeof cloudSave==='function'){ try{ cloudSave(); }catch(e){} } if(typeof dbUpsertConfig==='function') dbUpsertConfig(); /* Etapa 3 */
  _stxToast('Técnico ' + nome + ' autorizado — aguarde o selo "salvo na nuvem".');
  renderAdminDashboard();
}

function removeAllowedUser(idx){
  if(!isAdmin() && !window._adminUnlocked){ alert('Para remover técnicos, destrave o Painel com a senha de administrador.'); return; }
  ensureConfig();
  var users = data.__config.allowedUsers;
  if(idx >= 0 && idx < users.length) {
    var nome = users[idx] ? users[idx].nome : '';
    var remEmail = (users[idx] && typeof users[idx].email==='string') ? users[idx].email.toLowerCase().trim() : '';
    if(remEmail){ if(!data.__config.delUsers||typeof data.__config.delUsers!=='object') data.__config.delUsers={}; data.__config.delUsers[remEmail]=Date.now(); } /* lápide: não ressuscita no merge */
    users.splice(idx, 1);
    save(); if(typeof cloudSave==='function'){ try{ cloudSave(); }catch(e){} } if(typeof dbUpsertConfig==='function') dbUpsertConfig(); /* Etapa 3 */
    _stxToast('Técnico ' + nome + ' removido — aguarde "salvo na nuvem".');
    renderAdminDashboard();
  }
}

// Detecção de URL admin (?admin ou #admin)
if(window.location.search.indexOf('admin')>=0 || window.location.hash.indexOf('admin')>=0){
  history.replaceState(null, "", window.location.pathname);
  setTimeout(function(){ openAdminPanel(); }, 800);
}

/* ===== Tema claro/escuro: classe .light no <html>, persistida em localStorage ===== */
function toggleTheme(){
  var r=document.documentElement, light=!r.classList.contains('light');
  r.classList.add('theming'); clearTimeout(window._thT); window._thT=setTimeout(function(){r.classList.remove('theming');},420);
  r.classList.toggle('light', light);
  try{ localStorage.setItem('agracta-theme', light?'light':'dark'); }catch(e){}
  try{ var m=document.querySelector('meta[name="theme-color"]'); if(m) m.content=light?'#f2f3f1':'#101513'; }catch(e){}
  try{ closeMainMenu(); }catch(e){}
  if(typeof _stxToast==='function') _stxToast(light?'◐ Tema claro ativado':'◑ Tema escuro ativado');
}

/* ===== Inputs numéricos: seleciona o valor ao focar — digitar substitui em vez de concatenar (ex.: "1" + tecla "2" virava "12") ===== */
document.addEventListener('focusin', function(e){
  var el=e.target;
  if(!el || el.tagName!=='INPUT') return;
  if(el.type!=='number' && el.inputMode!=='numeric' && el.inputMode!=='decimal') return;
  setTimeout(function(){ try{ if(document.activeElement===el) el.select(); }catch(_){} }, 0);
});

/* ===================== SOLO — classe pedológica da quadra (Embrapa / SiBCS) =========
   O solo era o único dado de caracterização que continuava sendo digitado à mão, a
   cada protocolo, como "solo argiloso". Sem procedência, sem poder cruzar com
   resultado nenhum. Como a quadra já tem polígono, dá para perguntar aos
   levantamentos pedológicos oficiais em vez de redigitar.

   Duas honestidades que este bloco precisa manter, porque o dado é cartográfico:

   1) ESCALA. O mapa nacional é 1:5.000.000 — diz a região, não o talhão. Só alguns
      estados têm 1:250.000. A ficha mostra sempre a escala REAL da resposta e avisa
      quando ela é grosseira, em vez de exibir uma classe com ar de verdade medida.
   2) CARTOGRÁFICO ≠ OBSERVADO. `cartografico` vem do mapa e pode ser reconsultado à
      vontade; `observado` é a análise de campo/laboratório e o mapa nunca a
      sobrescreve. Quem abre uma trincheira sabe mais que o levantamento.

   Quadra de laboratório não tem polígono e é pulada, como o NDVI já faz. ===== */
var SOLO_PROXY=NDVI_PROXY;              /* mesmo proxy do NDVI/clima, como CLIMA_PROXY */
var SOLO_CACHE_KEY='agracta-solo-v1', SOLO_CACHE_TTL=30*24*3600*1000;  /* solo não muda */
var SOLO_WMS='https://geoinfo.dados.embrapa.br/geoserver/ows';
var _soloSeq=0, _soloEstado={};         /* qid -> 'buscando' | 'erro' | null */

/* Cor por ordem do SiBCS — a mesma lógica aditiva de CC/FEN lá no topo do arquivo. */
var SOLO_CORES={Latossolo:'#b5502e',Argissolo:'#c8763c',Nitossolo:'#9c3b2a',
  Neossolo:'#c9a227',Cambissolo:'#8a6d3b',Gleissolo:'#4a7c8c',Planossolo:'#7d8a9c',
  Plintossolo:'#a05a5a',Luvissolo:'#b08d57',Chernossolo:'#4a4a3a',
  Espodossolo:'#6b5b7b',Organossolo:'#3d3226',Vertissolo:'#5a5a4a',_:'#8a7f6a'};
function soloCor(ordem){ return SOLO_CORES[ordem]||SOLO_CORES._; }

/* ----- Estado guardado em data[qid].solo — sem schema novo -----
   _rowQuadra joga toda chave desconhecida de data[qid] em `extras`, e a leitura
   devolve inteira: Supabase e Firebase sincronizam de graça, e o merge é
   chave-a-chave. Mesmo caminho que data[qid].tipo usou. */
function soloDaQuadra(id){ var d=(typeof data!=='undefined'&&data[id])||{}; return (d.solo&&d.solo.cartografico)||null; }
function soloObservado(id){ var d=(typeof data!=='undefined'&&data[id])||{}; return (d.solo&&d.solo.observado)||null; }

function _soloGeom(id){
  ensureQGEO();
  var pts=QGEO&&QGEO[id]; if(!pts||pts.length<3) return null;
  var ring=pts.map(function(p){return [p[1],p[0]];}); ring.push(ring[0]);  /* GeoJSON é lng,lat */
  return {type:'Polygon', coordinates:[ring]};
}

/* Cache local por coordenada arredondada (~110 m), no molde do cache de datas do
   NDVI em ui-campo.js. Serve para quadra nova em região já consultada não precisar
   de rede — e para o app de campo responder offline. */
function _soloChaveCoord(ctr){ return ctr?((+ctr[0]).toFixed(3)+'|'+(+ctr[1]).toFixed(3)):null; }
function _soloLerCache(k){
  if(!k) return null;
  try{
    var c=JSON.parse(localStorage.getItem(SOLO_CACHE_KEY)||'null');
    if(c&&c[k]&&(Date.now()-c[k].ts)<SOLO_CACHE_TTL) return c[k].val;
  }catch(e){}
  return null;
}
function _soloGravarCache(k,val){
  if(!k||!val) return;
  try{
    var c=JSON.parse(localStorage.getItem(SOLO_CACHE_KEY)||'null')||{};
    c[k]={ts:Date.now(), val:val};
    var ks=Object.keys(c);
    if(ks.length>60){ ks.sort(function(a,b){return c[a].ts-c[b].ts;}); delete c[ks[0]]; }
    localStorage.setItem(SOLO_CACHE_KEY, JSON.stringify(c));
  }catch(e){}
}

/* PONTO ÚNICO DE ESCRITA do registro de solo.
   Três vezes neste módulo o objeto foi montado do zero e apagou em silêncio a
   metade que não vinha daquela operação — a mesma armadilha do saveE(). Em vez de
   lembrar de carregar tudo adiante em cada lugar, só se aplica o pedaço que mudou:
   o que não veio no patch permanece por construção. */
function _soloSet(id, patch){
  if(!data[id]) return;
  var solo=data[id].solo||{};
  for(var k in patch){ if(Object.prototype.hasOwnProperty.call(patch,k)) solo[k]=patch[k]; }
  data[id].solo=solo;
  data[id]._ts=Date.now();
  try{ save(); }catch(e){}
  try{ if(typeof dbUpsertQuadra==='function') dbUpsertQuadra(id); }catch(e){}
}
function _soloGravar(id, cart){ _soloSet(id, {cartografico:cart}); }

/* Consulta a classe pedológica da quadra. Molde do _carimboNdvi: pede, valida os
   dois níveis (r.ok e d.error) e chama de volta — nunca falha em silêncio. */
function consultarSolo(id, cb, forcar){
  cb=cb||function(){};
  if(typeof isQuadraLab==='function' && isQuadraLab(id)){ cb(null); return; }
  var geom=_soloGeom(id);
  if(!geom){ cb(null); return; }
  if(!forcar && soloDaQuadra(id)){ cb(soloDaQuadra(id)); return; }

  var ctr=quadraCenter(id), chave=_soloChaveCoord(ctr);
  if(!forcar){
    var doCache=_soloLerCache(chave);
    if(doCache){ _soloGravar(id, doCache); cb(doCache); return; }
  }

  var seq=++_soloSeq;
  _soloEstado[id]='buscando';
  try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}

  fetch(SOLO_PROXY+'/solo?geom='+encodeURIComponent(JSON.stringify(geom)))
    .then(function(r){ if(r&&r.ok===false) throw new Error('o servidor respondeu '+r.status); return r.json(); })
    .then(function(d){
      if(seq!==_soloSeq) return;                    /* resposta atrasada de outra quadra */
      if(!d||d.error) throw new Error((d&&d.error)||'resposta vazia');
      var cart={
        fonte:d.fonte||'embrapa-wfs', camada:d.camada||null, titulo:d.titulo||null,
        classe:d.classe||null, ordem:d.ordem||null, sigla:d.sigla||null,
        escala:d.escala||null, escalaN:d.escalaN||null, sibcs:d.sibcs||null,
        unidades:d.unidades||[], metodo:d.metodo||null,
        semCobertura:!!d.semCobertura,
        /* procedência, na forma do carimbo: quando foi consultado e por qual versão */
        ts:Date.now(), iso:new Date().toISOString(), app:(typeof APP_VER!=='undefined'?APP_VER:null)
      };
      _soloEstado[id]=null;
      _soloGravarCache(chave, cart);
      _soloGravar(id, cart);
      try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}
      cb(cart);
    })
    .catch(function(err){
      if(seq!==_soloSeq) return;
      _soloEstado[id]={erro:(err&&err.message)||String(err)};
      try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}
      cb(null);
    });
}

/* Botão da ficha: reconsulta ignorando cache. Só o cartográfico é refeito. */
function soloAtualizar(id){ consultarSolo(id, null, true); }
function soloReconsultar(id){ soloAtualizar(id); }

/* Polígono editado ⇒ a classe pode ter mudado de unidade. Reconsulta e marca
   `revisadoEm`, sem tocar no `ts` original — a mesma regra de imutabilidade que
   _recarimbaEvento usa: o registro original é histórico, não se reescreve. */
function soloRevisar(id){
  var ant=soloDaQuadra(id);
  if(!ant) return;
  consultarSolo(id, function(novo){
    if(!novo) return;
    novo.ts=ant.ts; novo.iso=ant.iso;         /* preserva o primeiro registro */
    novo.revisadoEm=Date.now();
    _soloGravar(id, novo);
  }, true);
}

/* ----- Ficha do solo dentro do painel da quadra ----- */
function _soloCss(){
  if(document.getElementById('soloCss')) return;
  var s=document.createElement('style'); s.id='soloCss';
  s.textContent='.solo-box{margin-top:12px;border-top:1px solid var(--gp-line,rgba(255,255,255,.09));padding-top:10px;font:12px system-ui,sans-serif}'+
   '.solo-h{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:7px}'+
   '.solo-h b{font-size:10px;letter-spacing:.8px;color:var(--gp-text-3,#727c75);font-weight:700}'+
   '.solo-rf{background:none;border:1px solid var(--gp-line,rgba(255,255,255,.14));color:var(--gp-text-3,#8b968e);border-radius:7px;padding:3px 9px;font-size:10px;font-weight:700;cursor:pointer}'+
   '.solo-rf:hover{color:var(--gp-text,#e9ede9);border-color:rgba(255,255,255,.3)}'+
   '.solo-cl{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:700;color:var(--gp-text,#e9ede9);line-height:1.3}'+
   '.solo-dot{flex:none;width:10px;height:10px;border-radius:3px}'+
   '.solo-meta{margin-top:5px;display:flex;gap:12px;flex-wrap:wrap;font-size:10.5px;color:var(--gp-text-3,#727c75)}'+
   '.solo-meta b{color:var(--gp-text,#c9d2cb);font-weight:700}'+
   '.solo-src{display:inline-block;border-radius:999px;padding:1px 7px;font-size:9.5px;font-weight:700;letter-spacing:.3px;border:1px solid}'+
   '.solo-src.ok{color:#7fc99a;border-color:rgba(127,201,154,.4);background:rgba(127,201,154,.1)}'+
   '.solo-src.no{color:#c9a97f;border-color:rgba(201,169,127,.4);background:rgba(201,169,127,.1)}'+
   '.solo-av{margin-top:7px;border-radius:8px;padding:7px 9px;font-size:11px;line-height:1.45;border:1px solid}'+
   '.solo-av.grossa{color:#d8bb7a;border-color:rgba(216,187,122,.32);background:rgba(216,187,122,.08)}'+
   '.solo-av.mix{color:#9ec4e0;border-color:rgba(158,196,224,.32);background:rgba(158,196,224,.08)}'+
   '.solo-un{margin-top:5px;display:flex;flex-direction:column;gap:3px}'+
   '.solo-ui{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--gp-text-2,#a8b3aa)}'+
   '.solo-ui i{flex:none;width:8px;height:8px;border-radius:2px;font-style:normal}'+
   '.solo-ui b{color:var(--gp-text,#e9ede9);font-weight:700;min-width:34px}'+
   '.solo-est{color:var(--gp-text-3,#727c75);font-size:11.5px}'+
   '.solo-sub{margin-top:10px;padding-top:9px;border-top:1px dashed var(--gp-line,rgba(255,255,255,.09))}'+
   '.solo-grid{margin-top:6px;display:grid;grid-template-columns:repeat(auto-fit,minmax(78px,1fr));gap:6px}'+
   '.solo-card{background:rgba(255,255,255,.035);border:1px solid var(--gp-line,rgba(255,255,255,.08));border-radius:8px;padding:6px 8px}'+
   '.solo-card .lab{font-size:9.5px;letter-spacing:.3px;color:var(--gp-text-3,#727c75);font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}'+
   '.solo-card .val{font-size:14px;font-weight:700;color:var(--gp-text,#e9ede9);margin-top:2px}'+
   '.solo-card .val small{font-size:9.5px;font-weight:600;color:var(--gp-text-3,#727c75)}'+
   '.solo-card .der{font-size:9px;color:var(--gp-text-3,#727c75);margin-top:2px}'+
   '.solo-form{margin-top:8px}'+
   '.solo-f{margin-bottom:7px}'+
   '.solo-f label{display:block;font-size:9.5px;letter-spacing:.5px;color:var(--gp-text-3,#727c75);font-weight:700;margin-bottom:3px}'+
   '.solo-f input,.solo-f select{width:100%;box-sizing:border-box;background:rgba(0,0,0,.25);border:1px solid var(--gp-line,rgba(255,255,255,.14));border-radius:7px;color:var(--gp-text,#e9ede9);padding:7px 8px;font-size:12.5px;font-family:inherit}'+
   '.solo-fb{display:flex;gap:6px;margin-top:9px}'+
   '.solo-ok{background:#1f5a2a;color:#eafaea;border:none;border-radius:7px;padding:6px 13px;font-size:11px;font-weight:700;cursor:pointer}'+
   '.solo-ok:hover{background:#246a31}';
  document.head.appendChild(s);
}

function soloBlocoHtml(id){
  if(typeof isQuadraLab==='function' && isQuadraLab(id)) return '';
  _soloCss();
  var est=_soloEstado[id], s=soloDaQuadra(id);
  var h='<div class="solo-box"><div class="solo-h"><b>SOLO</b>';
  if(!est || !est.erro) h+='<button class="solo-rf" onclick="soloAtualizar(\''+esc(id)+'\')">'+(s?'Reconsultar':'Consultar')+'</button>';
  h+='</div>';

  /* Estados explicam o que está acontecendo em vez de sumir — o chip do clima
     ensinou que sumir vira "o app está quebrado" na cabeça de quem usa. */
  if(est==='buscando') return h+'<div class="solo-est">Consultando solo…</div></div>';
  if(est&&est.erro) return h+'<div class="solo-est">Solo indisponível — '+esc(est.erro)+
    ' <button class="solo-rf" onclick="soloAtualizar(\''+esc(id)+'\')">Tentar de novo</button></div></div>';
  if(!s) return h+'<div class="solo-est">Ainda não consultado.</div>'+soloObsHtml(id)+soloAnaliseHtml(id)+soloCalagemHtml(id)+soloRecomendacaoHtml(id)+'</div>';
  if(s.semCobertura) return h+'<div class="solo-est">Sem cobertura pedológica mapeada para esta coordenada.</div>'+
    '<div class="solo-meta"><span>Consultado em <b>'+esc(_soloQuando(s))+'</b></span></div>'+
    soloObsHtml(id)+soloAnaliseHtml(id)+soloCalagemHtml(id)+soloRecomendacaoHtml(id)+'</div>';

  h+='<div class="solo-cl"><span class="solo-dot" style="background:'+soloCor(s.ordem)+'"></span>'+esc(s.classe||'—')+'</div>';
  h+='<div class="solo-meta">';
  if(s.ordem) h+='<span>Ordem <b>'+esc(s.ordem)+'</b></span>';
  if(s.sigla) h+='<span>Unidade <b>'+esc(s.sigla)+'</b></span>';
  if(s.escala) h+='<span>Escala <b>'+esc(s.escala)+'</b></span>';
  if(s.sibcs) h+='<span>SiBCS <b>'+esc(s.sibcs)+'</b></span>';
  h+='<span class="solo-src ok">Embrapa</span>';
  h+='</div>';

  /* 1:1.000.000 ou pior não caracteriza talhão. Dizer isso é o mínimo para o dado
     não ser usado como se fosse análise. */
  if(s.escalaN && s.escalaN>=1000000) h+='<div class="solo-av grossa">⚠ Escala '+esc(s.escala)+
    ' — indicativo regional, não caracterização de talhão. Confirme por análise de campo.</div>';

  var un=s.unidades||[];
  if(un.length>1){
    h+='<div class="solo-av mix">⚠ A quadra atravessa '+un.length+' unidades pedológicas. '+
       'A média do ensaio vai misturar solos diferentes.</div><div class="solo-un">';
    un.forEach(function(u){
      h+='<div class="solo-ui"><i style="background:'+soloCor(u.ordem)+'"></i><b>'+(u.pct!=null?u.pct+'%':'—')+'</b>'+
         esc(u.sigla?(u.sigla+' · '+(u.classe||'')):(u.classe||'—'))+'</div>';
    });
    h+='</div>';
  }

  h+='<div class="solo-meta" style="margin-top:6px"><span>Consultado em <b>'+esc(_soloQuando(s))+'</b></span>';
  if(s.titulo) h+='<span>Fonte <b>'+esc(s.titulo)+'</b></span>';
  if(s.revisadoEm) h+='<span>Revisado após edição do polígono</span>';
  h+='</div>';

  h+=soloObsHtml(id);
  h+=soloAnaliseHtml(id);
  h+=soloCalagemHtml(id);
  h+=soloRecomendacaoHtml(id);
  return h+'</div>';
}
function _soloQuando(s){
  try{ return new Date(s.ts).toLocaleDateString('pt-BR'); }catch(e){ return '—'; }
}

/* Texto curto para o relatório e para quem só quer a classe. */
function soloTexto(id){
  var s=soloDaQuadra(id);
  if(!s||s.semCobertura||!s.classe) return '';
  return s.classe;
}

/* Classe de solo para o relatório. Precedência: o que foi DIGITADO no protocolo
   vence sempre — quem preencheu à mão viu a área, e um dado cartográfico derivado
   não tem autoridade para apagar isso. O automático só ocupa a célula que hoje sai
   vazia. Observado em campo vence o cartográfico pela mesma razão. */
function soloClasseRelatorio(id, proto){
  var manual=proto&&proto.classeSolo;
  if(manual&&String(manual).trim()) return String(manual).trim();
  var ob=soloObservado(id);
  if(ob&&ob.classe&&String(ob.classe).trim()) return String(ob.classe).trim();
  return soloTexto(id);
}

/* ----- Propriedades edáficas estimadas (SoilGrids) -----
   Estimativa de modelo global, NÃO análise de solo. A tela tem de dizer isso: um
   número com cara de laudo, sem laudo por trás, é exatamente o tipo de dado que
   volta como conclusão errada num relatório. Servem para caracterizar o ambiente
   do ensaio — nunca para embasar recomendação de adubação. */
var _soloPropSeq=0, _soloPropEstado={};
function _soloPropValidar(pr){
  if(!pr||typeof pr!=='object') return false;
  if(pr.semCobertura) return true;
  var p=pr.propriedades;
  if(!p||typeof p!=='object') return false;
  var lim={clay:[0,100],sand:[0,100],silt:[0,100],phh2o:[2,12],soc:[0,1000],mo:[0,1724],cec:[0,200],bdod:[0.2,2.5]};
  var algum=false, invalido=false;
  Object.keys(lim).forEach(function(k){
    if(!p[k])return;
    var n=Number(p[k].valor), r=lim[k];
    if(!isFinite(n)||n<r[0]||n>r[1]) invalido=true;
    else algum=true;
  });
  var frac=['clay','sand','silt'];
  if(frac.every(function(k){return p[k]&&isFinite(Number(p[k].valor));})){
    var soma=frac.reduce(function(a,k){return a+Number(p[k].valor);},0);
    if(soma<85||soma>115) invalido=true;
  }
  return algum&&!invalido;
}
function soloPropriedades(id){
  var d=(typeof data!=='undefined'&&data[id])||{}, pr=(d.solo&&d.solo.propriedades)||null;
  /* Versões antigas aceitaram o índice da banda WMS como valor (0,1% para
     argila/areia/silte). Nunca volta a mostrar nem reutilizar esse registro. */
  return _soloPropValidar(pr)?pr:null;
}

function consultarSoloPropriedades(id, cb, forcar){
  cb=cb||function(){};
  if(typeof isQuadraLab==='function' && isQuadraLab(id)){ cb(null); return; }
  var ctr=quadraCenter(id);
  if(!ctr){ cb(null); return; }
  if(!forcar && soloPropriedades(id)){ cb(soloPropriedades(id)); return; }

  var seq=++_soloPropSeq;
  _soloPropEstado[id]='buscando';
  try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}

  fetch(SOLO_PROXY+'/solo/propriedades?lat='+ctr[0].toFixed(6)+'&lng='+ctr[1].toFixed(6))
    .then(function(r){ if(r&&r.ok===false) throw new Error('o servidor respondeu '+r.status); return r.json(); })
    .then(function(d){
      if(seq!==_soloPropSeq) return;
      if(!d||d.error) throw new Error((d&&d.error)||'resposta vazia');
      var pr={
        fonte:d.fonte||'soilgrids', referencia:d.referencia||null,
        estimativa:true, profundidade:d.profundidade||null,
        propriedades:d.propriedades||{}, textura:d.textura||null,
        semCobertura:!!d.semCobertura,
        ts:Date.now(), iso:new Date().toISOString(), app:(typeof APP_VER!=='undefined'?APP_VER:null)
      };
      if(!_soloPropValidar(pr)) throw new Error('a estimativa recebida é inconsistente; tente novamente');
      _soloPropEstado[id]=null;
      _soloSet(id, {propriedades:pr});
      try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}
      cb(pr);
    })
    .catch(function(err){
      if(seq!==_soloPropSeq) return;
      _soloPropEstado[id]={erro:(err&&err.message)||String(err)};
      try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}
      cb(null);
    });
}
function soloPropAtualizar(id){ consultarSoloPropriedades(id, null, true); }

function soloPropHtml(id){
  var est=_soloPropEstado[id], pr=soloPropriedades(id);
  var h='<div class="solo-sub"><div class="solo-h"><b>PROPRIEDADES ESTIMADAS</b>';
  if(est!=='buscando') h+='<button class="solo-rf" onclick="soloPropAtualizar(\''+esc(id)+'\')">'+(pr?'Reconsultar':'Consultar')+'</button>';
  h+='</div>';
  if(est==='buscando') return h+'<div class="solo-est">Consultando propriedades…</div></div>';
  if(est&&est.erro) return h+'<div class="solo-est">Propriedades indisponíveis — '+esc(est.erro)+'</div></div>';
  if(!pr) return h+'<div class="solo-est">Ainda não consultadas.</div></div>';
  if(pr.semCobertura) return h+'<div class="solo-est">Sem estimativa disponível para esta coordenada.</div></div>';

  var ordem=['clay','sand','silt','phh2o','soc','mo','cec','bdod'];
  h+='<div class="solo-grid">';
  ordem.forEach(function(k){
    var v=pr.propriedades[k]; if(!v) return;
    h+='<div class="solo-card"><div class="lab">'+esc(v.rotulo||k)+'</div><div class="val">'+
       esc(String(v.valor).replace('.',','))+(v.unidade?' <small>'+esc(v.unidade)+'</small>':'')+'</div>'+
       (v.derivada?'<div class="der">'+esc(v.derivada)+'</div>':'')+'</div>';
  });
  h+='</div>';
  if(pr.textura) h+='<div class="solo-meta" style="margin-top:6px"><span>Textura <b>'+esc(pr.textura)+'</b></span></div>';
  /* O aviso não é decorativo: é o que impede o número de ser lido como laudo. */
  h+='<div class="solo-av grossa">⚠ Estimativa de modelo global ('+esc(pr.referencia||'SoilGrids')+
     (pr.profundidade?', '+esc(pr.profundidade):'')+') — <b>não substitui análise de solo</b> '+
     'e não deve embasar recomendação de adubação.</div>';
  h+='<div class="solo-meta" style="margin-top:5px"><span>Consultado em <b>'+esc(_soloQuando(pr))+'</b></span>'+
     '<span class="solo-src no">estimativa</span></div>';
  return h+'</div>';
}

/* ----- Solo observado: o que a pessoa viu, e que o mapa nunca sobrescreve -----
   A análise completa de fertilidade é outro módulo (banco de análises). Aqui fica
   só a caracterização de campo: classe observada, textura, quem viu e quando. */
var SOLO_TEXTURAS=['','arenosa','média','argilosa','muito argilosa','siltosa','orgânica'];
function soloEditarObservado(id){
  var ob=soloObservado(id)||{};
  var alvo=document.getElementById('soloObsForm');
  if(!alvo) return;
  var opts=SOLO_TEXTURAS.map(function(t){
    return '<option value="'+esc(t)+'"'+(ob.textura===t?' selected':'')+'>'+esc(t||'—')+'</option>';
  }).join('');
  alvo.innerHTML=
    '<div class="solo-f"><label>CLASSE OBSERVADA</label>'+
    '<input id="soloObsClasse" type="text" placeholder="ex.: Latossolo Vermelho" value="'+esc(ob.classe||'')+'"></div>'+
    '<div class="solo-f"><label>TEXTURA</label><select id="soloObsTextura">'+opts+'</select></div>'+
    '<div class="solo-f"><label>DATA DA OBSERVAÇÃO</label>'+
    '<input id="soloObsData" type="date" value="'+esc(ob.data||'')+'"></div>'+
    '<div class="solo-f"><label>OBSERVAÇÃO</label>'+
    '<input id="soloObsNota" type="text" placeholder="trincheira, tradagem, laudo…" value="'+esc(ob.nota||'')+'"></div>'+
    '<div class="solo-fb"><button class="solo-ok" onclick="soloSalvarObservado(\''+esc(id)+'\')">Salvar</button>'+
    '<button class="solo-rf" onclick="soloCancelarObservado()">Cancelar</button>'+
    (ob.classe?'<button class="solo-rf" onclick="soloApagarObservado(\''+esc(id)+'\')">Apagar</button>':'')+'</div>';
  alvo.style.display='block';
}
function soloCancelarObservado(){
  var alvo=document.getElementById('soloObsForm');
  if(alvo){ alvo.style.display='none'; alvo.innerHTML=''; }
}
function _soloVal(id){ var el=document.getElementById(id); return el?String(el.value||'').trim():''; }
function soloSalvarObservado(id){
  if(!data[id]) return;
  var classe=_soloVal('soloObsClasse');
  var ant=data[id].solo||{};
  var obAnt=ant.observado||{};
  /* Autoria e carimbo seguem a regra BPL: `user` é o nome da pessoa (o que vira
     assinatura), e o registro original nunca é reescrito — edição marca revisão. */
  var ob={
    classe:classe, textura:_soloVal('soloObsTextura'), data:_soloVal('soloObsData'),
    nota:_soloVal('soloObsNota'), fonte:'manual',
    user:(typeof _currentUserName==='function'?(_currentUserName()||'Não identificado'):'Não identificado'),
    ts:(obAnt.ts||Date.now()), iso:(obAnt.iso||new Date().toISOString()),
    app:(typeof APP_VER!=='undefined'?APP_VER:null)
  };
  if(obAnt.ts) ob.revisadoEm=Date.now();
  _soloSet(id, {observado:(classe?ob:null)});
  soloCancelarObservado();
  try{ if(typeof _stxToast==='function') _stxToast(classe?'Solo observado salvo':'Solo observado removido'); }catch(e){}
  try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}
}
function soloApagarObservado(id){
  var el=document.getElementById('soloObsClasse'); if(el) el.value='';
  soloSalvarObservado(id);
}
function soloObsHtml(id){
  var ob=soloObservado(id);
  var h='<div class="solo-sub"><div class="solo-h"><b>OBSERVADO EM CAMPO</b>'+
        '<button class="solo-rf" onclick="soloEditarObservado(\''+esc(id)+'\')">'+(ob&&ob.classe?'Editar':'Registrar')+'</button></div>';
  if(ob&&ob.classe){
    h+='<div class="solo-cl" style="font-size:12.5px"><span class="solo-dot" style="background:'+soloCor(_soloOrdemDe(ob.classe))+'"></span>'+esc(ob.classe)+'</div>';
    h+='<div class="solo-meta">';
    if(ob.textura) h+='<span>Textura <b>'+esc(ob.textura)+'</b></span>';
    if(ob.data) h+='<span>Em <b>'+esc(_soloDataBR(ob.data))+'</b></span>';
    if(ob.user) h+='<span>Por <b>'+esc(ob.user)+'</b></span>';
    h+='<span class="solo-src ok">campo</span></div>';
    if(ob.nota) h+='<div class="solo-meta"><span>'+esc(ob.nota)+'</span></div>';
    if(ob.revisadoEm) h+='<div class="solo-meta"><span>Revisado depois do primeiro registro</span></div>';
  }else{
    h+='<div class="solo-est">Nada registrado. O que for anotado aqui vence o mapa.</div>';
  }
  return h+'<div id="soloObsForm" class="solo-form" style="display:none"></div></div>';
}
function _soloDataBR(iso){
  if(!iso) return '';
  var p=String(iso).split('-');
  return p.length===3?(p[2]+'/'+p[1]+'/'+p[0]):String(iso);
}
/* Mesma leitura de ordem do SiBCS que o proxy faz, para o ponto colorido do
   observado combinar com o do cartográfico. */
function _soloOrdemDe(txt){
  var n=String(txt||'').toLowerCase()
    .replace(/[áàâã]/g,'a').replace(/[éê]/g,'e').replace(/í/g,'i')
    .replace(/[óôõ]/g,'o').replace(/[úü]/g,'u').replace(/ç/g,'c');
  var ordens=Object.keys(SOLO_CORES);
  for(var i=0;i<ordens.length;i++){
    if(ordens[i]!=='_' && n.indexOf(ordens[i].toLowerCase())>=0) return ordens[i];
  }
  return null;
}

/* ===================== ANÁLISE DE SOLO E RECOMENDAÇÃO ==============================
   O solo cartográfico diz a CLASSE (Latossolo, Argissolo…). Ele não serve para
   recomendar adubação: é interpolação de mapa, não medição. Quem recomenda é a
   análise de fertilidade do laboratório. Por isso as duas coisas vivem separadas,
   e só a análise alimenta o cálculo.

   A análise pertence a um EVENTO DATADO, não à quadra: `analises` é uma lista, cada
   entrada com data, laboratório e profundidade. Assim dá para ver a evolução de pH,
   V% e P ao longo dos anos, e a recomendação sempre diz de qual análise saiu.

   Os índices derivados (SB, CTC, V%, m%) são CALCULADOS, nunca digitados. Um laudo
   pode trazê-los, mas se a pessoa digitar Ca, Mg, K e também um V% que não fecha com
   eles, o app teria dois números discordando sem saber qual vale. Calcular sempre
   elimina a dúvida — e a trilha mostra a conta. ===== */

/* Unidade de cada entrada do laudo. Fixa a unidade na tela e nos testes: laudo em
   mmolc/dm³ e laudo em cmolc/dm³ diferem por um fator 10, e trocar isso em silêncio
   erra a calagem por dez vezes. */
var SOLO_ANALISE_CAMPOS=[
  {k:'pH',  rot:'pH (CaCl₂)', un:'',           passo:'0.1'},
  {k:'MO',  rot:'Matéria orgânica', un:'g/dm³',passo:'1'},
  {k:'P',   rot:'P (resina)', un:'mg/dm³',     passo:'1'},
  {k:'K',   rot:'K',          un:'mmolc/dm³',  passo:'0.1'},
  {k:'Ca',  rot:'Ca',         un:'mmolc/dm³',  passo:'1'},
  {k:'Mg',  rot:'Mg',         un:'mmolc/dm³',  passo:'1'},
  {k:'HAl', rot:'H+Al',       un:'mmolc/dm³',  passo:'1'},
  {k:'Al',  rot:'Al',         un:'mmolc/dm³',  passo:'0.1'},
  {k:'S',   rot:'S',          un:'mg/dm³',     passo:'1'},
  {k:'B',   rot:'B',          un:'mg/dm³',     passo:'0.01'},
  {k:'Cu',  rot:'Cu',         un:'mg/dm³',     passo:'0.1'},
  {k:'Fe',  rot:'Fe',         un:'mg/dm³',     passo:'1'},
  {k:'Mn',  rot:'Mn',         un:'mg/dm³',     passo:'0.1'},
  {k:'Zn',  rot:'Zn',         un:'mg/dm³',     passo:'0.1'}
];

function soloAnalises(id){
  var d=(typeof data!=='undefined'&&data[id])||{};
  var a=(d.solo&&d.solo.analises)||[];
  /* Mais recente primeiro: é a que vale para recomendar. */
  return a.slice().sort(function(x,y){ return String(y.data||'').localeCompare(String(x.data||'')); });
}
function soloAnaliseAtual(id){ var a=soloAnalises(id); return a.length?a[0]:null; }

/* Índices derivados. Definições universais de química de solo, não tabela de
   recomendação: SB é a soma das bases, T a CTC a pH 7, V% a saturação por bases e
   m% a saturação por alumínio. */

/* Bloco da janela no cartão da avaliação. Nasce fechado como um resumo de uma linha:
   a leitura de relance é "14 dias, 72 mm, média 24,6" — o resto se abre. */
function janelaBlocoHtml(qid, sid, av){
  var study=(data[qid]&&(data[qid].estudos||[]).filter(function(s){return s.id===sid;})[0])||null;
  if(!study) return '';
  var j=janelaDaAvaliacao(av);
  var chave=_janelaChave(qid,sid,av.id);
  var estado=_janelaEstado[chave];

  if(!j){
    var ap=janelaAplicacaoAnterior(study, av);
    if(!ap || ap.data===av.data) return '';   /* sem intervalo, não há o que oferecer */
    if(estado==='buscando') return '<div class="jan-linha">Montando a janela ambiental…</div>';
    return '<div class="jan-linha">'+
      '<button class="jan-btn" onclick="janelaBuscar(\''+esc(qid)+'\',\''+esc(sid)+'\',\''+esc(av.id)+'\')">'+
      '🌦 Ambiente desde a aplicação de '+esc(isoToBR(ap.data)||ap.data)+'</button>'+
      (estado==='erro'?'<span class="jan-erro">não consegui na última tentativa</span>':'')+'</div>';
  }

  var h='<div class="jan-bloco"><div class="jan-t">AMBIENTE ENTRE A APLICAÇÃO DE '+
        esc(isoToBR(j.de)||j.de)+' E ESTA AVALIAÇÃO</div>'+
        '<div class="jan-resumo">'+esc(janelaResumo(j))+'</div>';
  var det=[];
  if(j.tempMin!=null) det.push('mín '+String(j.tempMin).replace('.',',')+' °C');
  if(j.urMedia!=null) det.push('UR média '+String(j.urMedia).replace('.',',')+'%');
  if(j.rajadaMax!=null) det.push('rajada máx '+String(j.rajadaMax).replace('.',',')+' km/h');
  if(j.radiacaoMedia!=null) det.push('radiação média '+String(j.radiacaoMedia).replace('.',',')+' W/m²');
  if(det.length) h+='<div class="jan-det">'+esc(det.join(' · '))+'</div>';
  var cob=janelaCobertura(j);
  if(cob) h+='<div class="jan-cob">⚠ '+esc(cob)+'</div>';
  h+='<div class="jan-pe">'+esc((j.fonte==='ecowitt-historico'?'Estação ':'')+'· lido em '+
     (function(){ try{ return new Date(j.ts).toLocaleString('pt-BR'); }catch(e){ return j.iso; } })())+
     '<button class="jan-btn mini" onclick="janelaBuscar(\''+esc(qid)+'\',\''+esc(sid)+'\',\''+esc(av.id)+'\',1)">reconsultar</button></div>';
  return h+'</div>';
}

function janelaBuscar(qid, sid, avid, forcar){
  var study=(data[qid]&&(data[qid].estudos||[]).filter(function(s){return s.id===sid;})[0])||null;
  var av=study&&(study.avaliacoes||[]).filter(function(a){return a.id===avid;})[0];
  if(!av) return;
  _janelaEstado[_janelaChave(qid,sid,avid)]='buscando';
  try{ openStudyDetail(qid,sid); }catch(e){}
  consultarJanela(qid, sid, av, !!forcar, function(r){
    if(r&&r.erro && typeof _stxToast==='function') _stxToast(r.erro);
    try{ openStudyDetail(qid,sid); }catch(e){}
  });
}



/* ===================== CHUVA DEPOIS DA APLICAÇÃO =================================
   A janela ambiental responde "o que aconteceu ENTRE a aplicação e a avaliação".
   Falta a pergunta que decide se a aplicação valeu: choveu LOGO DEPOIS? Produto
   lavado três horas após a pulverização não é produto que não funcionou — e sem
   esse dado o ensaio conclui a coisa errada com toda a confiança do mundo.

   O carimbo já guarda o instante e o clima da hora da pulverização; a estação já
   guarda o histórico. O que faltava era o fio: nada olhava para as horas
   SEGUINTES.

   A conta mora no proxy (`/clima/pos`), pela mesma razão da janela: são N
   chamadas à Ecowitt, o fan-out é dele, e o cache aproveita entre estudos da
   mesma estação. Aqui fica o que só o app pode fazer — guardar o que foi lido.

   E vale o mesmo que vale para a janela: FICA GRAVADA, não recalculada. A leitura
   muda quando a Ecowitt reprocessa, num registro BPL vale o que foi lido quando se
   registrou, e a aplicação precisa abrir offline. Reconsultar não apaga: a
   anterior vira histórico.

   DUAS DECLARAÇÕES ACOMPANHAM O NÚMERO, SEMPRE. Se a aplicação não tem hora, a
   conta é do dia inteiro — e "choveu 12 mm depois de pulverizar" vira "choveu
   12 mm no dia em que se pulverizou", que é outra frase. E se a janela ainda não
   fechou, 0 mm não é resposta: é uma janela aberta. ============================= */

var _posSeq=0, _posEstado={};      /* chave -> 'buscando' | 'erro' | null */
var POS_HORAS_PADRAO=48;

function posDaAplicacao(ap){ return (ap&&ap.pos)||null; }
function _posChave(qid, sid, apid){ return 'pos|'+qid+'|'+sid+'|'+apid; }

function consultarPos(qid, sid, ap, horas, forcar, cb){
  cb=cb||function(){};
  var study=(data[qid]&&(data[qid].estudos||[]).filter(function(s){return s.id===sid;})[0])||null;
  if(!study||!ap||!ap.data){ cb(null); return; }
  if(ap.pos && !forcar){ cb(ap.pos); return; }

  /* Numa bancada não chove. Oferecer isso ali seria a §7-bis de novo. */
  if(typeof isQuadraLab==='function' && isQuadraLab(qid)){
    cb({erro:'Aplicação de bancada não tem chuva depois.'}); return;
  }
  var mac=(typeof _stationMacForQuadra==='function')?_stationMacForQuadra(qid):null;
  if(!mac){ cb({erro:'Esta quadra não tem estação meteorológica associada.'}); return; }

  var h=Math.max(1,parseInt(horas||POS_HORAS_PADRAO,10)||POS_HORAS_PADRAO);
  var chave=_posChave(qid,sid,ap.id), seq=++_posSeq;
  _posEstado[chave]='buscando';
  var url=NDVI_PROXY+'/clima/pos?mac='+encodeURIComponent(mac)+
          '&data='+encodeURIComponent(ap.data)+
          (ap.hora?('&hora='+encodeURIComponent(String(ap.hora).slice(0,5))):'')+
          '&horas='+encodeURIComponent(h);
  fetch(url).then(function(r){ return r.json(); }).then(function(d){
    if(seq!==_posSeq && _posEstado[chave]!=='buscando') return;
    if(!d || d.error){ _posEstado[chave]='erro'; cb({erro:(d&&d.error)||'Não consegui ler a chuva depois da aplicação.'}); return; }
    _posEstado[chave]=null;
    var p={
      data:ap.data, hora:(ap.hora||null), horas:d.horas,
      horaConhecida:!!d.hora_conhecida, completa:!!d.completa,
      dias:d.dias, diasComLeitura:d.dias_com_leitura, coberturaPct:d.cobertura_pct,
      diasSemLeitura:(d.dias_sem_leitura||[]),
      chuvaMm:d.chuva_mm, choveu:d.choveu,
      primeiraChuvaHoras:d.primeira_chuva_horas,
      fonte:d.fonte, mac:mac, ts:Date.now(), iso:new Date().toISOString(),
      app:(typeof APP_VER!=='undefined'?APP_VER:null)
    };
    if(ap.pos){ ap.posAnteriores=(ap.posAnteriores||[]); ap.posAnteriores.push(ap.pos); }
    ap.pos=p;
    ap._ts=Date.now();
    try{ save(); }catch(e){}
    try{ if(typeof dbUpsertAplicacao==='function') dbUpsertAplicacao(qid,sid,ap); }catch(e){}
    cb(p);
  }).catch(function(){
    _posEstado[chave]='erro';
    cb({erro:'Não consegui falar com o servidor de clima.'});
  });
}

/* Uma linha, do jeito que se lê em voz alta: "18 mm nas 48 h seguintes — a
   primeira chuva 3,2 h depois". */
function posResumo(p){
  if(!p||p.erro) return (p&&p.erro)||'';
  var horas=p.horas+' h';
  if(p.chuvaMm==null) return 'sem leitura da estação nas '+horas+' seguintes';
  function n(v){ return (v==null||!isFinite(v))?null:String(Number(v).toFixed(1)).replace('.',','); }
  if(!p.choveu) return 'não choveu nas '+horas+' seguintes';
  var s=n(p.chuvaMm)+' mm nas '+horas+' seguintes';
  if(p.primeiraChuvaHoras!=null) s+=' — a primeira chuva '+n(p.primeiraChuvaHoras)+' h depois';
  return s;
}

/* As ressalvas não são rodapé: cada uma muda como se lê o número de cima. */
function posRessalvas(p){
  if(!p||p.erro) return [];
  var r=[];
  if(!p.completa) r.push('A janela ainda não fechou: o total acima é parcial e vai mudar.');
  if(!p.horaConhecida) r.push('A aplicação não registrou hora, então a conta é do DIA INTEIRO — '+
    'a chuva que caiu antes de pulverizar está incluída.');
  if(p.coberturaPct<100){
    if(!p.diasComLeitura) r.push('A estação não tinha leitura em nenhum dia desta janela — nada acima pôde ser calculado.');
    else r.push('Atenção: '+p.diasComLeitura+' de '+p.dias+' dias com leitura ('+p.coberturaPct+'%). '+
                'A chuva dos dias sem leitura não entra no total.');
  }
  return r;
}

function posBlocoHtml(qid, sid, ap){
  if(!ap||!ap.data) return '';
  if(typeof isQuadraLab==='function' && isQuadraLab(qid)) return '';
  var p=posDaAplicacao(ap);
  var chave=_posChave(qid,sid,ap.id), estado=_posEstado[chave];

  if(!p){
    if(estado==='buscando') return '<div class="jan-linha">Lendo a chuva depois da aplicação…</div>';
    return '<div class="jan-linha">'+
      '<button class="jan-btn" onclick="posBuscar(\''+esc(qid)+'\',\''+esc(sid)+'\',\''+esc(ap.id)+'\')">'+
      '🌧 Choveu depois? (48 h)</button>'+
      (estado==='erro'?'<span class="jan-erro">não consegui na última tentativa</span>':'')+'</div>';
  }

  var lavou=(p.chuvaMm!=null && p.choveu && p.primeiraChuvaHoras!=null && p.primeiraChuvaHoras<=6);
  var h='<div class="jan-bloco'+(lavou?' pos-lavou':'')+'"><div class="jan-t">CHUVA DEPOIS DESTA APLICAÇÃO</div>'+
        '<div class="jan-resumo">'+esc(posResumo(p))+'</div>';
  /* Chuva nas primeiras horas não é detalhe do rodapé: é a explicação mais
     provável de um resultado ruim, e quem lê o cartão precisa tropeçar nela. */
  if(lavou) h+='<div class="jan-det pos-alerta">⚠ Chuva nas primeiras horas depois da aplicação — '+
    'considere a possibilidade de lavagem ao interpretar este ensaio.</div>';
  var res=posRessalvas(p);
  if(res.length) h+='<div class="jan-cob">⚠ '+res.map(esc).join('<br>⚠ ')+'</div>';
  h+='<div class="jan-pe">Estação · lido em '+
     esc((function(){ try{ return new Date(p.ts).toLocaleString('pt-BR'); }catch(e){ return p.iso; } })())+
     '<button class="jan-btn mini" onclick="posBuscar(\''+esc(qid)+'\',\''+esc(sid)+'\',\''+esc(ap.id)+'\',24,1)">24 h</button>'+
     '<button class="jan-btn mini" onclick="posBuscar(\''+esc(qid)+'\',\''+esc(sid)+'\',\''+esc(ap.id)+'\',48,1)">48 h</button>'+
     '<button class="jan-btn mini" onclick="posBuscar(\''+esc(qid)+'\',\''+esc(sid)+'\',\''+esc(ap.id)+'\',72,1)">72 h</button>'+
     '</div>';
  return h+'</div>';
}

function posBuscar(qid, sid, apid, horas, forcar){
  var study=(data[qid]&&(data[qid].estudos||[]).filter(function(s){return s.id===sid;})[0])||null;
  var ap=study&&(study.aplicacoes||[]).filter(function(a){return a.id===apid;})[0];
  if(!ap) return;
  _posEstado[_posChave(qid,sid,apid)]='buscando';
  try{ openStudyDetail(qid,sid); }catch(e){}
  consultarPos(qid, sid, ap, horas||POS_HORAS_PADRAO, !!forcar, function(r){
    if(r&&r.erro && typeof _stxToast==='function') _stxToast(r.erro);
    try{ openStudyDetail(qid,sid); }catch(e){}
  });
}

/* ===================== BANCO DE ITENS E DOSES ====================================
   Até aqui o produto de um tratamento era uma STRING digitada. "Sankari", "sankari",
   "SANKARI 500 SC" e "Sankari (lote novo)" eram quatro produtos diferentes para o
   app, e nenhum deles se ligava a nada: nem ao registro, nem à bula, nem ao mesmo
   produto num outro ensaio. Comparar dois estudos exigia um humano lembrando que os
   dois textos eram a mesma coisa.

   O catálogo dá IDENTIDADE ao item. Cadastra-se uma vez — o item do cliente chega,
   entra aqui — e ele passa a ser selecionável em qualquer protocolo. Daí em diante,
   "onde mais este item foi testado" vira uma pergunta que o app pode responder.

   TRÊS COISAS SÃO DIFERENTES, e confundi-las é o erro que este módulo evita:

     ITEM   — a identidade. O que o produto É.
     DOSE   — quanto se pretende usar, PARA QUAL cultura e alvo. Uma dose solta
              ("1 L/ha") não significa nada: 1 L/ha em soja contra ferrugem e 1 L/ha
              em milho contra lagarta são duas informações, não uma.
     LOTE   — o material fisico recebido. Cada entrada, consumo, movimentacao,
              ajuste e descarte entra num livro-razão somente de acrescimo, com
              data, responsavel e documento. O protocolo pode apontar para o lote,
              sem transformar dose planejada em consumo fisico inventado.

   ONDE MORA: coleção GLOBAL, como LOCAIS e RZLIB — não pendurada numa quadra. Um item
   é da organização, não de um talhão. Entra em cloudState() pelo mesmo caminho, com
   mapa de timestamps para o merge e lápides para exclusão.

   O QUE ESTE MÓDULO NÃO FAZ: recomendar. Ele guarda o que a bula diz e o que o
   patrocinador mandou, com a origem à vista. Escolher a dose continua sendo do
   pesquisador, e dose fora da indicação registrada é permitida — com justificativa,
   porque ensaio experimental existe para isso. ================================== */

var ITENS_KEY='agracta-itens-v1', ITENSTS_KEY='agracta-itens-ts-v1', DELITENS_KEY='agracta-itens-del-v1';
var ITENS=null, ITENS_TS=null;
var _delItens=(function(){ try{ return JSON.parse(localStorage.getItem(DELITENS_KEY)||'{}')||{}; }catch(e){ return {}; } })();

/* Os tipos que um ensaio precisa distinguir. Não é taxonomia de gosto: o tipo muda o
   que a tela pede e o que o relatório imprime. */
var ITEM_TIPOS=[
  ['teste',      'Item-teste experimental'],
  ['referencia', 'Referência / produto registrado'],
  ['adjuvante',  'Adjuvante'],
  ['fertilizante','Fertilizante ou nutricional'],
  ['biologico',  'Agente biológico'],
  ['padrao',     'Padrão analítico'],
  ['veiculo',    'Veículo, controle ou outro componente']
];
var ITEM_SITUACOES=[
  ['registrado','Registrado'], ['experimental','Experimental'], ['ret','RET'],
  ['cancelado','Cancelado'], ['na','Não aplicável']
];
/* De onde a dose veio. É o campo mais importante da dose: um número sem origem não
   se defende numa auditoria, e "0,8 L/ha" da bula e "0,8 L/ha porque o patrocinador
   pediu" são registros diferentes. */
var DOSE_ORIGENS=[
  ['bula',        'Indicação registrada (bula)'],
  ['patrocinador','Do patrocinador'],
  ['experimental','Hipótese experimental'],
  ['historica',   'Usada em ensaio anterior'],
  ['manual',      'Informada manualmente']
];
function itemTipoRotulo(k){ var x=ITEM_TIPOS.filter(function(t){return t[0]===k;})[0]; return x?x[1]:(k||''); }
function doseOrigemRotulo(k){ var x=DOSE_ORIGENS.filter(function(t){return t[0]===k;})[0]; return x?x[1]:(k||''); }

function ensureItens(){
  if(!ITENS){ try{ ITENS=JSON.parse(localStorage.getItem(ITENS_KEY)||'{}')||{}; }catch(e){ ITENS={}; } }
  if(!ITENS_TS){ try{ ITENS_TS=JSON.parse(localStorage.getItem(ITENSTS_KEY)||'{}')||{}; }catch(e){ ITENS_TS={}; } }
  return ITENS;
}
function saveItens(){
  try{ localStorage.setItem(ITENS_KEY, JSON.stringify(ITENS||{})); }catch(e){}
  try{ localStorage.setItem(ITENSTS_KEY, JSON.stringify(ITENS_TS||{})); }catch(e){}
  try{ localStorage.setItem(DELITENS_KEY, JSON.stringify(_delItens||{})); }catch(e){}
}
function _touchItem(id){ ensureItens(); ITENS_TS[id]=Date.now(); saveItens(); }

/* Chave de comparação para achar duplicata. Sem isto o catálogo vira lista de
   sinônimos em dois meses e para de ser identidade — que é a única coisa que ele
   tinha para oferecer. */
function _itemChave(nome){
  return normStr(nome).replace(/[^a-z0-9]+/g,' ').trim();
}
/* Itens cujo nome bate com este, ignorando caixa, acento e pontuação. Não funde
   sozinho: apenas mostra, para a pessoa decidir. Fusão automática de cadastro é
   como se perde dado sem ninguém notar. */
function itemPossiveisDuplicatas(nome, exceto){
  ensureItens();
  var k=_itemChave(nome); if(!k) return [];
  return Object.keys(ITENS).filter(function(id){
    if(id===exceto || _delItens[id]) return false;
    var it=ITENS[id]||{};
    if(_itemChave(it.nome)===k) return true;
    return (it.sinonimos||[]).some(function(s){ return _itemChave(s)===k; });
  }).map(function(id){ return ITENS[id]; });
}

function itensLista(){
  ensureItens();
  return Object.keys(ITENS).filter(function(id){ return !_delItens[id]; })
    .map(function(id){ return ITENS[id]; })
    .sort(function(a,b){ return String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'); });
}
function itemPorId(id){ ensureItens(); return (id&&!_delItens[id])?(ITENS[id]||null):null; }

function itemNovo(dados){
  ensureItens();
  dados=dados||{};
  var nome=String(dados.nome||'').trim();
  if(!nome) return null;
  var id=(dados.id||('it'+uid().slice(1)));
  delete _delItens[id];
  ITENS[id]={
    id:id,
    nome:nome,
    codigo:String(dados.codigo||'').trim(),        /* codigo experimental do patrocinador */
    sinonimos:Array.isArray(dados.sinonimos)?dados.sinonimos.slice():[],
    tipo:(ITEM_TIPOS.some(function(t){return t[0]===dados.tipo;})?dados.tipo:'teste'),
    situacao:(ITEM_SITUACOES.some(function(t){return t[0]===dados.situacao;})?dados.situacao:'experimental'),
    titular:String(dados.titular||'').trim(),      /* cliente / patrocinador / fabricante */
    registro:String(dados.registro||'').trim(),
    formulacao:String(dados.formulacao||'').trim(),
    concentracao:String(dados.concentracao||'').trim(),
    ativos:String(dados.ativos||'').trim(),
    armazenamento:String(dados.armazenamento||'').trim(),
    obs:String(dados.obs||'').trim(),
    /* Código cego: em ensaio de patrocinador o executor não pode ver a identidade.
       Guardar o campo desde o começo é barato; retroencaixá-lo depois de o item
       aparecer em relatório e exportação é caro. */
    codigoCego:String(dados.codigoCego||'').trim(),
    doses:Array.isArray(dados.doses)?dados.doses.slice():[],
    lotes:Array.isArray(dados.lotes)?dados.lotes.slice():[],
    /* Vínculos históricos preservam a identidade de estudos já assinados sem
       escrever dentro deles. É a conciliação auditável, externa ao registro
       congelado, que permite a matriz enxergar o passado. */
    vinculosHistoricos:Array.isArray(dados.vinculosHistoricos)?dados.vinculosHistoricos.slice():[],
    criadoEm:Date.now(),
    criadoPor:(typeof _currentUserName==='function'?(_currentUserName()||''):'')
  };
  _touchItem(id);
  try{ if(typeof save==='function') save(); }catch(e){}
  return ITENS[id];
}
function itemAtualizar(id, patch){
  var it=itemPorId(id); if(!it) return null;
  if(Object.prototype.hasOwnProperty.call(patch||{},'nome') && !String(patch.nome||'').trim()) return null;
  for(var k in patch){
    if(Object.prototype.hasOwnProperty.call(patch,k) && ['id','doses','lotes','vinculosHistoricos','criadoEm','criadoPor'].indexOf(k)<0) it[k]=patch[k];
  }
  it.revisadoEm=Date.now();
  _touchItem(id);
  try{ if(typeof save==='function') save(); }catch(e){}
  return it;
}
/* Exclusão por lápide, como quadras e locais: sem isso um aparelho que sincroniza
   depois ressuscita o item apagado. */
function itemExcluir(id){
  if(!itemPorId(id)) return false;
  _delItens[id]=Date.now();
  saveItens();
  try{ if(typeof save==='function') save(); }catch(e){}
  return true;
}

/* ---- Doses ----
   A dose PERTENCE ao item e é qualificada por cultura e alvo. "0,8 L/ha" sozinho não
   é informação: precisa dizer em quê e contra o quê. Tudo o mais é opcional — um
   cadastro que exige doze campos por dose não é preenchido, e aí o pesquisador volta
   a digitar o nome do produto à mão, que é exatamente o que o catálogo veio acabar. */
function itemDoses(id){ var it=itemPorId(id); return it?(it.doses||(it.doses=[])):[]; }

function itemDoseAdicionar(id, d){
  var it=itemPorId(id); if(!it) return null;
  if(!Array.isArray(it.doses)) it.doses=[];
  d=d||{};
  var valor=(d.valor===''||d.valor==null)?null:Number(String(d.valor).replace(',','.'));
  var valorMax=(d.valorMax===''||d.valorMax==null)?null:Number(String(d.valorMax).replace(',','.'));
  var aplicacoesMax=(d.aplicacoesMax===''||d.aplicacoesMax==null)?null:Number(d.aplicacoesMax);
  var intervaloDias=(d.intervaloDias===''||d.intervaloDias==null)?null:Number(d.intervaloDias);
  var unidade=String(d.unidade||'L/ha').trim(); if(unidade==='%') unidade='% v/v';
  if(!(valor>0) || !isFinite(valor)) return {erro:'Informe uma dose numérica maior que zero.'};
  if(valorMax!=null && (!isFinite(valorMax) || valorMax<valor)) return {erro:'O fim da faixa deve ser um número igual ou maior que a dose inicial.'};
  if(aplicacoesMax!=null && (!isFinite(aplicacoesMax) || aplicacoesMax<1 || Math.floor(aplicacoesMax)!==aplicacoesMax)) return {erro:'Aplicações máximas deve ser um número inteiro maior que zero.'};
  if(intervaloDias!=null && (!isFinite(intervaloDias) || intervaloDias<0 || Math.floor(intervaloDias)!==intervaloDias)) return {erro:'O intervalo deve ser um número inteiro não negativo.'};
  if(window.DoseCore&&DoseCore.UNIDADES&&!DoseCore.UNIDADES[unidade]) return {erro:'Escolha uma unidade de dose válida.'};
  var dose={
    id:('ds'+uid().slice(1)),
    cultura:String(d.cultura||'').trim(),
    alvo:String(d.alvo||'').trim(),
    valor:valor,
    valorMax:valorMax,
    unidade:unidade,
    volumeCalda:String(d.volumeCalda||'').trim(),
    modalidade:String(d.modalidade||'').trim(),
    aplicacoesMax:aplicacoesMax,
    intervaloDias:intervaloDias,
    epoca:String(d.epoca||'').trim(),
    restricoes:String(d.restricoes||'').trim(),
    origem:(DOSE_ORIGENS.some(function(o){return o[0]===d.origem;})?d.origem:'manual'),
    documento:String(d.documento||'').trim(),      /* bula, ficha tecnica, e-mail do cliente */
    pagina:String(d.pagina||'').trim(),
    consultadoEm:String(d.consultadoEm||'').trim(),
    situacao:'ativa',
    criadaEm:Date.now()
  };
  it.doses.push(dose);
  _touchItem(id);
  try{ if(typeof save==='function') save(); }catch(e){}
  return dose;
}
/* Dose não se apaga: ela some da escolha mas continua existindo, porque um protocolo
   antigo pode tê-la usado e o registro daquele ensaio não pode ficar apontando para
   o nada. */
function itemDoseAposentar(id, doseId){
  var d=(itemDoses(id)||[]).filter(function(x){ return x.id===doseId; })[0];
  if(!d) return false;
  d.situacao='substituida';
  d.aposentadaEm=Date.now();
  _touchItem(id);
  try{ if(typeof save==='function') save(); }catch(e){}
  return true;
}

/* Doses que servem para ESTA cultura e ESTE alvo. Dose sem cultura declarada serve
   para qualquer uma — é o caso do adjuvante, que não é específico. */
function itemDosesPara(id, cultura, alvo){
  var c=normStr(cultura||''), a=normStr(alvo||'');
  return (itemDoses(id)||[]).filter(function(d){
    if(d.situacao!=='ativa') return false;
    if(d.cultura && c && normStr(d.cultura)!==c) return false;
    if(d.alvo && a && normStr(d.alvo)!==a) return false;
    return true;
  });
}
/* Como a dose se lê numa linha. É este texto que vai para o seletor do protocolo. */
function doseTexto(d){
  if(!d) return '';
  function n(v){ return (v==null||!isFinite(v))?'':String(v).replace('.',','); }
  var faixa=n(d.valor)+((d.valorMax!=null&&isFinite(d.valorMax)&&d.valorMax!==d.valor)?('–'+n(d.valorMax)):'');
  var p=[];
  if(d.cultura) p.push(d.cultura);
  if(d.alvo) p.push(d.alvo);
  p.push(faixa+(d.unidade?(' '+d.unidade):''));
  return p.join(' · ');
}

/* ---- Lotes e cadeia de custodia ----
   O saldo nunca e digitado por cima. Ele e a soma de eventos imutaveis pelo app;
   quando houve erro, registra-se um AJUSTE com justificativa. Isso deixa a trilha
   entendivel numa auditoria e impede que uma edicao silenciosa apague o caminho do
   material entre recebimento, armazenamento e ensaio. */
var LOTE_EVENTOS=['recebimento','entrada','movimentacao','consumo','ajuste','descarte','devolucao'];
function itemLotes(id){
  var it=itemPorId(id); if(!it) return [];
  if(!Array.isArray(it.lotes)) it.lotes=[];
  return it.lotes;
}
function itemLotePorId(itemId,loteId){
  return itemLotes(itemId).filter(function(l){ return l&&l.id===loteId; })[0]||null;
}
function _itemNumero(v){
  if(v===''||v==null) return null;
  var n=(typeof v==='number')?v:Number(String(v).replace(',','.'));
  return isFinite(n)?n:null;
}
function _loteImpacto(tipo,q){
  if(tipo==='recebimento'||tipo==='entrada') return q;
  if(tipo==='consumo'||tipo==='descarte'||tipo==='devolucao') return -q;
  if(tipo==='ajuste') return q;
  return 0;
}
function itemLoteSaldo(lote){
  if(!lote) return 0;
  var saldo=(lote.eventos||[]).reduce(function(s,e){
    if(!e) return s;
    var n=_itemNumero(e.impacto);
    if(n==null){
      var q=_itemNumero(e.quantidade)||0;
      n=_loteImpacto(e.tipo,q);
    }
    return s+n;
  },0);
  return Math.round(saldo*1000000)/1000000;
}
function itemLotesAtivos(itemId){
  return itemLotes(itemId).filter(function(l){ return l&&l.situacao!=='encerrado'&&itemLoteSaldo(l)>0; });
}
function _loteEventoMontar(lote,d){
  d=d||{};
  var tipo=String(d.tipo||'').trim();
  if(LOTE_EVENTOS.indexOf(tipo)<0) return {erro:'Tipo de movimentação inválido.'};
  var q=_itemNumero(d.quantidade);
  if(tipo==='ajuste'){
    if(q==null||q===0) return {erro:'O ajuste precisa informar uma quantidade diferente de zero.'};
    if(!String(d.obs||'').trim()) return {erro:'Explique o motivo do ajuste; ele não pode alterar o saldo em silêncio.'};
  }else if(!(q>0)) return {erro:'Informe uma quantidade maior que zero.'};
  var unidade=String(d.unidade||lote.unidade||'').trim();
  if(!unidade) return {erro:'Informe a unidade do lote.'};
  if(lote.unidade && normStr(unidade)!==normStr(lote.unidade)) return {erro:'A movimentação deve usar a mesma unidade do lote ('+lote.unidade+').'};
  var impacto=_loteImpacto(tipo,q);
  var saldo=itemLoteSaldo(lote)+impacto;
  if(saldo < -0.0000001) return {erro:'Saldo insuficiente: este evento deixaria o lote negativo.'};
  return {evento:{
    id:'ev'+uid().slice(1), tipo:tipo, em:String(d.em||new Date().toISOString().slice(0,10)),
    quantidade:q, unidade:unidade, impacto:impacto,
    origem:String(d.origem||'').trim(), destino:String(d.destino||'').trim(),
    estudoId:String(d.estudoId||'').trim(), tratamentoId:String(d.tratamentoId||'').trim(),
    /* Um consumo que não sabe de que aplicação saiu é meia trilha: o inventário
       fecha, mas "onde este material foi parar" volta a depender de memória
       humana. A aplicação e o componente vão gravados no evento. */
    aplicacaoId:String(d.aplicacaoId||'').trim(), componenteId:String(d.componenteId||'').trim(),
    origemRegistro:String(d.origemRegistro||'manual').trim(),
    documento:String(d.documento||'').trim(), responsavel:String(d.responsavel||
      (typeof _currentUserName==='function'?(_currentUserName()||''):'')).trim(),
    obs:String(d.obs||'').trim(), registradoEm:Date.now(), saldoApos:Math.max(0,Math.round(saldo*1000000)/1000000)
  }};
}
function itemLoteNovo(itemId,d){
  var it=itemPorId(itemId); if(!it) return {erro:'Item não encontrado.'};
  d=d||{};
  var codigo=String(d.codigo||'').trim(), unidade=String(d.unidade||'').trim();
  var q=_itemNumero(d.quantidade);
  if(!codigo) return {erro:'Informe o código do lote.'};
  if(itemLotes(itemId).some(function(l){ return normStr(l.codigo)===normStr(codigo); })) return {erro:'Já existe um lote com esse código neste item.'};
  if(!(q>0)) return {erro:'Informe a quantidade recebida, maior que zero.'};
  if(!unidade) return {erro:'Informe a unidade física do lote.'};
  var lote={
    id:'lt'+uid().slice(1), codigo:codigo, recebidoEm:String(d.recebidoEm||new Date().toISOString().slice(0,10)),
    quantidadeInicial:q, unidade:unidade, validade:String(d.validade||'').trim(),
    fabricante:String(d.fabricante||'').trim(), fornecedor:String(d.fornecedor||'').trim(),
    documento:String(d.documento||'').trim(), armazenamento:String(d.armazenamento||it.armazenamento||'').trim(),
    responsavel:String(d.responsavel||(typeof _currentUserName==='function'?(_currentUserName()||''):'')).trim(),
    situacao:'ativo', obs:String(d.obs||'').trim(), criadoEm:Date.now(), eventos:[]
  };
  var montado=_loteEventoMontar(lote,{tipo:'recebimento',quantidade:q,unidade:unidade,em:lote.recebidoEm,
    origem:lote.fornecedor,documento:lote.documento,responsavel:lote.responsavel,obs:lote.obs});
  if(montado.erro) return montado;
  lote.eventos.push(montado.evento); itemLotes(itemId).push(lote); _touchItem(itemId);
  try{ if(typeof save==='function') save(); }catch(e){}
  return lote;
}
function itemLoteEvento(itemId,loteId,d){
  var lote=itemLotePorId(itemId,loteId); if(!lote) return {erro:'Lote não encontrado.'};
  if(lote.situacao==='encerrado') return {erro:'Este lote está encerrado.'};
  if(!Array.isArray(lote.eventos)) lote.eventos=[];
  var r=_loteEventoMontar(lote,d); if(r.erro) return r;
  lote.eventos.push(r.evento);
  lote.situacao=(r.evento.saldoApos<=0)?'esgotado':'ativo';
  lote.revisadoEm=Date.now(); _touchItem(itemId);
  try{ if(typeof save==='function') save(); }catch(e){}
  return {evento:r.evento,saldo:r.evento.saldoApos,lote:lote};
}

/* Conciliação de estudo finalizado: o tratamento assinado fica byte por byte como
   estava. A confirmação vive no item, com referência suficiente para voltar à
   origem. Repetir a mesma migração não cria uma segunda ocorrência. */
function itemVinculosHistoricos(itemId){
  var it=itemPorId(itemId); if(!it) return [];
  if(!Array.isArray(it.vinculosHistoricos)) it.vinculosHistoricos=[];
  return it.vinculosHistoricos;
}
function _vinculoHistoricoChave(v){ return [v.qid,v.estudoId,v.tratamentoId,v.componenteId||''].join('|'); }
function itemVincularHistorico(itemId,d){
  var it=itemPorId(itemId); if(!it) return {erro:'Item não encontrado.'};
  d=d||{};
  if(!d.qid||!d.estudoId||!d.tratamentoId) return {erro:'O vínculo histórico precisa apontar para quadra, estudo e tratamento.'};
  var vs=itemVinculosHistoricos(itemId), chave=_vinculoHistoricoChave(d);
  var existe=vs.filter(function(v){ return _vinculoHistoricoChave(v)===chave; })[0];
  if(existe) return {vinculo:existe,criado:false};
  var v={id:'vh'+uid().slice(1),qid:String(d.qid),quadra:String(d.quadra||d.qid),
    estudoId:String(d.estudoId),estudo:String(d.estudo||d.estudoId),tratamentoId:String(d.tratamentoId),
    componenteId:String(d.componenteId||''),produtoOriginal:String(d.produtoOriginal||''),
    dose:String(d.dose||''),cultura:String(d.cultura||''),origem:String(d.origem||'historica'),
    finalizado:true,confirmadoEm:Date.now(),confirmadoPor:String(d.confirmadoPor||
      (typeof _currentUserName==='function'?(_currentUserName()||''):'')).trim()};
  vs.push(v); _touchItem(itemId);
  try{ if(typeof save==='function') save(); }catch(e){}
  return {vinculo:v,criado:true};
}
function itemHistoricoJaVinculado(qid,estudoId,tratamentoId,componenteId){
  ensureItens(); var chave=[qid,estudoId,tratamentoId,componenteId||''].join('|'), achou=false;
  Object.keys(ITENS||{}).some(function(id){
    if(_delItens[id]) return false;
    achou=(ITENS[id].vinculosHistoricos||[]).some(function(v){ return _vinculoHistoricoChave(v)===chave; });
    return achou;
  });
  return achou;
}




/* ---- Tratamento como RECEITA (compositor) ----
   Um tratamento raramente é um produto só: "Produto A + adjuvante" é o caso comum, e
   programa sequencial é o caso difícil. Até aqui isso morava numa string —
   "Sankari + Silwet" — que o motor de calda sabia partir, mas que nada mais entendia:
   o catálogo não via dois itens, a estatística não via dois componentes, e "onde este
   adjuvante foi usado" não tinha resposta.

   t.componentes[] é a receita estruturada. t.produto e t.dose continuam existindo e
   continuam mandando quando não há componentes — de novo, migrar sem migração.

   A TESTEMUNHA NÃO É UM ITEM. Cadastrar "testemunha" como produto no banco seria
   inventar um produto que não existe, e ele apareceria em "onde foi usado" como se
   alguém o tivesse aplicado. Ela continua sendo o que sempre foi: uma marca no
   tratamento. */

function tratComponentes(t){
  if(!t) return [];
  if(!Array.isArray(t.componentes)) t.componentes=[];
  return t.componentes;
}
function tratTemReceita(t){ return tratComponentes(t).length>0; }

function tratCompAdicionar(t, itemId, valor, unidade, doseId){
  if(!t) return null;
  var it=itemPorId(itemId);
  var c={
    id:('cp'+uid().slice(1)),
    itemId:(it?it.id:null),
    nome:(it?(it.nome||''):String(itemId||'').trim()),   /* texto livre continua aceito */
    valor:(valor===''||valor==null)?null:Number(String(valor).replace(',','.')),
    unidade:String(unidade||'L/ha').trim(),
    doseRef:null
  };
  if(it && doseId){
    var d=(itemDoses(it.id)||[]).filter(function(x){ return x.id===doseId; })[0];
    if(d){
      c.valor=(d.valor!=null?d.valor:c.valor);
      c.unidade=(d.unidade||c.unidade);
      /* Mesmo congelamento da dose do tratamento: cópia, não referência. */
      c.doseRef={itemId:it.id, doseId:d.id, cultura:d.cultura, alvo:d.alvo,
                 valor:d.valor, valorMax:d.valorMax, unidade:d.unidade,
                 origem:d.origem, documento:d.documento, congeladoEm:Date.now()};
    }
  }
  tratComponentes(t).push(c);
  _tratSincronizaTexto(t);
  return c;
}
function tratCompRemover(t, compId){
  var cs=tratComponentes(t);
  var i=cs.map(function(c){return c.id;}).indexOf(compId);
  if(i<0) return false;
  cs.splice(i,1);
  _tratSincronizaTexto(t);
  return true;
}
/* O motor de calda (BioCalculoCampo.parseComponents) lê t.produto e t.dose como
   texto. Manter os dois em dia com a receita é o que permite a receita existir sem
   reescrever o motor — e sem que a tela e o cálculo discordem. */
function _tratSincronizaTexto(t){
  var cs=tratComponentes(t);
  if(!cs.length) return;
  t.produto=cs.map(function(c){ return c.nome||''; }).filter(Boolean).join(' + ');
  t.dose=cs.map(function(c){
    return (c.valor!=null?String(c.valor).replace('.',','):'')+(c.unidade?(' '+c.unidade):'');
  }).join(' + ');
}

/* ---- Escada de doses ----
   Ensaio de dose-resposta é quatro tratamentos que só diferem no multiplicador. Fazer
   as quatro contas à mão é onde se erra uma. */
function tratEscadaCriar(study, itemId, doseRef, unidade, multiplos, opts){
  var D=(typeof window!=='undefined')?window.DoseCore:null;
  if(!D) return {erro:'O motor de doses não carregou. Recarregue o app.'};
  if(!study) return {erro:'Sem estudo.'};
  opts=opts||{};
  var e=D.escada(doseRef, unidade, multiplos);
  if(e.erro) return e;
  var it=itemPorId(itemId);
  if(!it) return {erro:'Escolha um item do banco para montar a escada.'};

  if(!Array.isArray(study.tratamentos)) study.tratamentos=[];
  var criados=[];
  /* A testemunha entra PRIMEIRO e sem dose: ela é o zero da escada, e um ensaio de
     dose-resposta sem o zero não tem de onde partir. */
  if(opts.comTestemunha && !(study.tratamentos||[]).some(function(t){ return t.testemunha; })){
    var t0={id:_tratProximoId(study), produto:'Testemunha', dose:'0', testemunha:true, obs:''};
    study.tratamentos.push(t0); criados.push(t0);
  }
  e.degraus.forEach(function(g){
    var t={id:_tratProximoId(study), produto:'', dose:'', obs:'', componentes:[]};
    study.tratamentos.push(t);
    tratCompAdicionar(t, it.id, g.valor, g.unidade, null);
    t.escada={referencia:e.referencia, multiplo:g.multiplo, unidade:g.unidade, itemId:it.id};
    criados.push(t);
  });
  return {criados:criados, degraus:e.degraus};
}
/* T1, T2, T3… sem repetir o que já existe. */
function _tratProximoId(study){
  var usados={}; (study.tratamentos||[]).forEach(function(t){ if(t&&t.id) usados[String(t.id).toUpperCase()]=1; });
  for(var i=1;i<200;i++){ var c='T'+i; if(!usados[c]) return c; }
  return 'T'+((study.tratamentos||[]).length+1);
}

/* Equivalente em i.a. de um tratamento, quando o item declara concentração. Duas
   formulações a 1 L/ha não são a mesma dose se uma tem 250 g/L e a outra 500. */
function tratEquivalenteIA(t){
  var D=(typeof window!=='undefined')?window.DoseCore:null;
  if(!D) return null;
  var it=tratItem(t); if(!it || !it.concentracao) return null;
  var m=String(it.concentracao).match(/([\d.,]+)\s*(g\/L|g\/kg|%)/i);
  if(!m) return null;
  var v=_calcNum(t.dose), u=_calcDoseUnit(t.dose);
  if(!(v>0)) return null;
  var r=D.equivalenteIA(v, u, m[1].replace(',','.'), m[2].toLowerCase().replace('g/l','g/L').replace('g/kg','g/kg'));
  return (r&&!r.erro)?r:null;
}


/* ---- Migração: os estudos existentes não são recriados ----
   Trinta e tantos estudos já existem com o produto digitado à mão. Recriá-los para
   "modernizar" seria destruir dado real; deixá-los de fora seria fazer o relatório
   Item × Dose nascer vazio, porque o vínculo só existiria nos ensaios novos.

   Então: o Agracta VARRE o que foi digitado, agrupa os nomes iguais e PROPÕE ligar.
   Quem liga é a pessoa. Ligar sozinho seria adivinhar que "Sankari" e "Sankari 500"
   são o mesmo produto — e às vezes não são, porque uma formulação nova entra com o
   mesmo nome de campo.

   ESTUDO FINALIZADO NÃO SE TOCA. Ele foi congelado com assinatura e data; a
   identidade confirmada fica num vínculo histórico EXTERNO, dentro do item. Assim
   o registro assinado não muda, mas a matriz deixa de apagar o passado. */

/* Um nome digitado, com tudo o que se sabe sobre ele. Mistura vira DOIS candidatos:
   "Sankari + Silwet" são dois produtos, e tratá-los como um perderia o adjuvante. */
function migracaoCandidatos(){
  ensureItens();
  var mapa={}, finalizados=0;
  if(typeof data==='undefined'||!data) return {candidatos:[], finalizados:0};
  Object.keys(data).forEach(function(qid){
    if(qid==='__config') return;
    ((data[qid]||{}).estudos||[]).forEach(function(st){
      var fin=(typeof estudoFinalizado==='function')?estudoFinalizado(st):false;
      (st.tratamentos||[]).forEach(function(t){
        if(!t) return;
        if(t.itemId || tratTemReceita(t)) return;          /* já tem identidade */
        if(t.testemunha) return;                            /* testemunha não é item */
        if(fin && typeof itemHistoricoJaVinculado==='function' && itemHistoricoJaVinculado(qid,st.id,t.id,'')) return;
        var txt=String(t.produto||'').trim();
        if(!txt) return;
        /* Mesma separação que o motor de calda usa, para o que o app já sabe partir
           não ser agrupado de outro jeito aqui. */
        var partes=txt.split(/\s*\+\s*/).map(function(x){ return x.trim(); }).filter(Boolean);
        /* Um nome dentro de uma mistura conta separado do nome sozinho. Vincular
           "Sankari" quando o tratamento diz "Sankari + Silwet" trocaria uma mistura
           de dois produtos por um item so, perdendo o adjuvante: isso e trabalho do
           compositor de receita, nao de uma varredura. Contar junto faria a tela
           prometer "12 usos" e ligar 3 — o numero precisa ser honesto antes do clique. */
        var mistura=partes.length>1;
        partes.forEach(function(nome){
          var k=_itemChave(nome);
          if(!k) return;
          if(!mapa[k]) mapa[k]={chave:k, nome:nome, variantes:{}, ocorrencias:0, simples:0, emMistura:0,
                                finalizados:0, finalizadosSimples:0, finalizadosMistura:0,
                                estudos:{}, exemplos:[]};
          var c=mapa[k];
          c.variantes[nome]=(c.variantes[nome]||0)+1;
          c.ocorrencias++;
          if(fin){
            finalizados++; c.finalizados++;
            if(mistura) c.finalizadosMistura++; else c.finalizadosSimples++;
          }else if(mistura) c.emMistura++; else c.simples++;
          c.estudos[st.id]=1;
          if(c.exemplos.length<3) c.exemplos.push({qid:qid, estudo:(st.codigo||st.nome||st.id), trat:t.id,
                                                   dose:(t.dose||''), mistura:mistura, finalizado:fin});
        });
      });
    });
  });
  var out=Object.keys(mapa).map(function(k){
    var c=mapa[k];
    /* A grafia mais usada vira o nome proposto: é a que a equipe escreve de verdade. */
    var vs=Object.keys(c.variantes).sort(function(a,b){ return c.variantes[b]-c.variantes[a]; });
    c.nome=vs[0];
    c.grafias=vs;
    c.nEstudos=Object.keys(c.estudos).length;
    c.sugestoes=itemPossiveisDuplicatas(c.nome, null);
    return c;
  }).sort(function(a,b){
    /* O que da para ligar agora vem primeiro; o resto e leitura, nao trabalho. */
    var la=((a.simples+a.finalizadosSimples)>0?1:0), lb=((b.simples+b.finalizadosSimples)>0?1:0);
    if(la!==lb) return lb-la;
    return b.ocorrencias-a.ocorrencias;
  });
  return {candidatos:out, finalizados:finalizados,
          ligaveis:out.filter(function(c){ return (c.simples+c.finalizadosSimples)>0; }).length};
}

/* Liga TODOS os tratamentos abertos cujo produto bate com esta chave. Para um
   finalizado, cria a conciliação externa no item sem alterar o tratamento. */
function migracaoLigar(chave, itemId){
  var it=itemPorId(itemId); if(!it) return {erro:'Item não encontrado.'};
  var n=0, historicos=0, estudosTocados={};
  Object.keys(data||{}).forEach(function(qid){
    if(qid==='__config') return;
    ((data[qid]||{}).estudos||[]).forEach(function(st){
      var fin=(typeof estudoFinalizado==='function' && estudoFinalizado(st));
      (st.tratamentos||[]).forEach(function(t){
        if(!t || t.itemId || tratTemReceita(t) || t.testemunha) return;
        var partes=String(t.produto||'').split(/\s*\+\s*/).map(function(x){ return x.trim(); }).filter(Boolean);
        if(partes.length!==1) return;      /* mistura vira receita, não vínculo simples */
        if(_itemChave(partes[0])!==chave) return;
        if(fin){
          var vh=itemVincularHistorico(it.id,{qid:qid,quadra:(typeof quadraNome==='function'?quadraNome(qid):qid),
            estudoId:st.id,estudo:(st.codigo||st.nome||st.id),tratamentoId:t.id,
            produtoOriginal:partes[0],dose:(t.dose||''),
            cultura:(typeof studyCultura==='function'?studyCultura(st,data[qid]||{}):'')});
          if(vh&&vh.criado) historicos++;
          return;
        }
        tratLigarItem(t, it.id, null);
        /* A migração vai marcada: um vínculo criado por varredura não é a mesma coisa
           que um escolhido na hora de montar o protocolo. */
        t.itemMigrado={em:Date.now(), de:(t.produtoOriginal||partes[0]),
                       por:(typeof _currentUserName==='function'?(_currentUserName()||''):'')};
        n++; estudosTocados[st.id]=st;
      });
    });
  });
  Object.keys(estudosTocados).forEach(function(sid){
    try{
      if(typeof logStudyAuditInObject==='function')
        logStudyAuditInObject(estudosTocados[sid],'tratamento.item',
          'Produto digitado vinculado ao item "'+(it.nome||it.id)+'" do banco',
          {itemId:it.id, origem:'migracao'});
    }catch(e){}
  });
  try{ save(); }catch(e){}
  return {ligados:n, historicos:historicos, estudos:Object.keys(estudosTocados).length, item:it};
}

/* Cria o item a partir do que foi digitado e liga na mesma passada. É o caminho
   normal: quase todo nome digitado ainda não existe no banco. */
function migracaoCriarELigar(chave, nome, extra){
  var it=itemNovo(Object.assign({nome:nome}, extra||{}));
  if(!it) return {erro:'Informe o nome do item.',ligados:0,historicos:0};
  var r=migracaoLigar(chave, it.id);
  r.criado=true;
  return r;
}

/* ---- Telas ----
   A regra de tela é uma só: cadastrar um item tem de ser MAIS RÁPIDO que digitar o
   nome à mão. No instante em que não for, o pesquisador digita à mão e o catálogo
   morre. Por isso o cadastro pede quatro campos e o resto é opcional. */
var _itemAberto=null, _itemBusca='', _itemRascunho=null, _loteAberto=null;

function _itensCss(){
  if(document.getElementById('itensCss')) return;
  var s=document.createElement('style'); s.id='itensCss';
  s.textContent=
   '.it-ovl{position:fixed;inset:0;z-index:3400;background:rgba(0,0,0,.62);display:none;align-items:flex-start;justify-content:center;padding:14px;overflow:auto;-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px)}'+
   '.it-box{width:100%;max-width:640px;background:var(--surface,#101613);border:1px solid var(--border,#26322b);border-radius:16px;box-shadow:0 24px 70px rgba(0,0,0,.55);color:var(--text,#e8efe9);font-family:var(--font,system-ui);padding:16px;margin:auto}'+
   '.it-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}'+
   '.it-t{font-size:16px;font-weight:900}.it-x{background:none;border:0;color:var(--text-3,#7f9085);font-size:22px;cursor:pointer;line-height:1}'+
   '.it-busca{width:100%;box-sizing:border-box;background:var(--surface-2,#0c1210);border:1px solid var(--border,#26322b);border-radius:10px;color:var(--text,#e8efe9);padding:10px 12px;font-size:14px;outline:none;margin-bottom:10px}'+
   '.it-lin{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:9px 10px;border-radius:10px;border:1px solid var(--border,#26322b);margin-bottom:6px;cursor:pointer;background:var(--surface-2,#0c1210)}'+
   '.it-lin:hover{border-color:#7ba7d0}'+
   '.it-nome{font-weight:800;font-size:13.5px}.it-sub{font-size:11px;color:var(--text-3,#7f9085);margin-top:2px}'+
   '.it-tag{font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:#8fb6d8;background:rgba(120,170,215,.13);border:1px solid rgba(120,170,215,.3);border-radius:5px;padding:1px 6px;white-space:nowrap}'+
   '.it-f{margin-bottom:9px}.it-f label{display:block;font-size:10px;letter-spacing:.7px;text-transform:uppercase;color:var(--text-3,#7f9085);font-weight:800;margin-bottom:4px}'+
   '.it-f input,.it-f select,.it-f textarea{width:100%;box-sizing:border-box;background:var(--surface-2,#0c1210);border:1px solid var(--border,#26322b);border-radius:9px;color:var(--text,#e8efe9);padding:9px 10px;font-size:14px;outline:none;font-family:inherit}'+
   '.it-row{display:flex;gap:9px}.it-row>*{flex:1;min-width:0}'+
   '.it-btn{background:#1f7a44;color:#fff;border:0;border-radius:10px;padding:10px 14px;font-weight:800;cursor:pointer;font-family:inherit;font-size:13px}'+
   '.it-btn.alt{background:var(--surface-2,#0c1210);color:var(--text-2,#9fb1a5);border:1px solid var(--border,#26322b)}'+
   '.it-dup{background:rgba(220,205,140,.10);border:1px solid rgba(220,205,140,.32);color:#dccd8c;border-radius:9px;padding:8px 10px;font-size:11.5px;line-height:1.5;margin-bottom:9px}'+
   '.it-dose{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:7px 9px;border-radius:9px;border:1px solid var(--border,#26322b);margin-bottom:5px;font-size:12.5px}'+
   '.it-dose b{font-weight:800}.it-vazio{font-size:12px;color:var(--text-3,#7f9085);font-style:italic;padding:10px 0}';
  document.head.appendChild(s);
}
function _itOvl(){
  _itensCss();
  var o=document.getElementById('itensOvl');
  if(!o){ o=document.createElement('div'); o.id='itensOvl'; o.className='it-ovl';
    o.onclick=function(e){ if(e.target===o) fecharItens(); }; document.body.appendChild(o); }
  return o;
}
function fecharItens(){ var o=document.getElementById('itensOvl'); if(o) o.style.display='none'; _itemAberto=null; _itemRascunho=null; _loteAberto=null; _migAberta=false; }

function abrirItens(){
  if(typeof closeMainMenu==='function') closeMainMenu();
  ensureItens(); _itemAberto=null; _migAberta=false;
  /* Varre uma vez, na abertura. _itensPinta() roda a cada tecla da busca e a
     varredura passa por todos os estudos — refazer a cada letra seria desperdicio. */
  try{ _migPendentes=migracaoCandidatos().ligaveis; }catch(e){ _migPendentes=0; }
  var o=_itOvl(); o.style.display='flex'; _itensPinta();
}
function _itensBusca(v){ _itemBusca=v||''; _itensPinta(); }

function _itensPinta(){
  var o=document.getElementById('itensOvl'); if(!o) return;
  if(_migAberta){ o.innerHTML=_migracaoHtml(); return; }
  if(_itemAberto){ o.innerHTML=_itemFichaHtml(_itemAberto); return; }
  var q=normStr(_itemBusca), lista=itensLista().filter(function(it){
    if(!q) return true;
    return normStr(it.nome).indexOf(q)>=0 || normStr(it.codigo).indexOf(q)>=0 ||
           normStr(it.titular).indexOf(q)>=0 || normStr(it.ativos).indexOf(q)>=0;
  });
  var h='<div class="it-box"><div class="it-top"><div class="it-t">📦 Banco de itens</div>'+
        '<button class="it-x" onclick="fecharItens()" aria-label="Fechar">×</button></div>';
  h+='<input class="it-busca" placeholder="Buscar por nome, código, cliente ou ingrediente ativo" value="'+esc(_itemBusca)+'" oninput="_itensBusca(this.value)">';
  h+='<button class="it-btn" onclick="itemAbrirNovo()">+ Cadastrar item</button>';
  /* So aparece quando ha o que migrar. Um botao permanente para uma fila vazia e
     exatamente o tipo de ruido que a tela nao deve ter. */
  if(_migPendentes>0){
    h+='<button class="it-btn alt" onclick="migracaoAbrir()">🔗 '+_migPendentes+' produto'+(_migPendentes===1?'':'s')+
       ' ja digitado'+(_migPendentes===1?'':'s')+' esperando cadastro</button>';
  }
  h+='<div style="margin-top:12px">';
  if(!lista.length){
    h+='<div class="it-vazio">'+(_itemBusca?'Nenhum item com esse termo.':'Nenhum item cadastrado ainda. Cadastre uma vez e ele fica disponível em todos os protocolos.')+'</div>';
  }
  lista.forEach(function(it){
    var nd=(it.doses||[]).filter(function(d){return d.situacao==='ativa';}).length;
    h+='<div class="it-lin" onclick="itemAbrir(\''+esc(it.id)+'\')">'+
       '<div><div class="it-nome">'+esc(it.nome||'(sem nome)')+(it.codigo?(' <span style="opacity:.6;font-weight:600">'+esc(it.codigo)+'</span>'):'')+'</div>'+
       '<div class="it-sub">'+esc([itemTipoRotulo(it.tipo), it.titular, it.formulacao].filter(Boolean).join(' · '))+
       (nd?(' · '+nd+' dose'+(nd===1?'':'s')):' · sem dose')+'</div></div>'+
       '<span class="it-tag">'+esc(it.situacao||'')+'</span></div>';
  });
  h+='</div></div>';
  o.innerHTML=h;
}

function itemAbrir(id){ _itemAberto=id; _itemRascunho=null; _loteAberto=null; _itensPinta(); }
function itemVoltar(){ _itemAberto=null; _itemRascunho=null; _loteAberto=null; _itensPinta(); }

function itemAbrirNovo(){
  /* Rascunho so existe na tela. Antes, abrir este formulario ja persistia um item
     sem nome e ele podia sincronizar antes de a pessoa preencher ou cancelar. */
  _itemRascunho={tipo:'teste',situacao:'experimental'};
  _itemAberto='__novo__'; _itensPinta();
  setTimeout(function(){ var i=document.getElementById('itNome'); if(i) i.focus(); },50);
}

function _itemNovoHtml(){
  var h='<div class="it-box"><div class="it-top"><div class="it-t">Novo item</div>'+
        '<button class="it-x" onclick="fecharItens()" aria-label="Fechar">×</button></div>'+
        '<button class="it-btn alt" onclick="itemVoltar()">‹ Cancelar</button><div style="height:10px"></div>'+
        '<div class="it-f"><label>Nome *</label><input id="itNome" placeholder="como o cliente chama"></div>'+
        '<div class="it-row"><div class="it-f"><label>Código experimental</label><input id="itNovoCodigo" placeholder="ex.: XYZ-2026-01"></div>'+
        '<div class="it-f"><label>Cliente / titular</label><input id="itNovoTitular"></div></div>'+
        '<div class="it-row"><div class="it-f"><label>Tipo</label><select id="itNovoTipo">'+
        ITEM_TIPOS.map(function(t){return '<option value="'+t[0]+'">'+esc(t[1])+'</option>';}).join('')+'</select></div>'+
        '<div class="it-f"><label>Situação</label><select id="itNovoSituacao">'+
        ITEM_SITUACOES.map(function(t){return '<option value="'+t[0]+'"'+(t[0]==='experimental'?' selected':'')+'>'+esc(t[1])+'</option>';}).join('')+
        '</select></div></div><button class="it-btn" onclick="itemNovoSalvar()">Salvar item</button></div>';
  return h;
}
function itemNovoSalvar(){
  function v(id){var e=document.getElementById(id);return e?String(e.value||'').trim():'';}
  var nome=v('itNome'); if(!nome){alert('Informe o nome do item.');return;}
  var dup=itemPossiveisDuplicatas(nome,null);
  if(dup.length && !confirm('Já existe '+(dup.length===1?'um item':'itens')+' com este nome: '+
    dup.map(function(x){return x.nome;}).join(', ')+'.\n\nCadastrar mesmo assim?')) return;
  var it=itemNovo({nome:nome,codigo:v('itNovoCodigo'),titular:v('itNovoTitular'),
    tipo:v('itNovoTipo')||'teste',situacao:v('itNovoSituacao')||'experimental'});
  if(!it){alert('Não foi possível salvar o item.');return;}
  _itemRascunho=null;_itemAberto=it.id;_itensPinta();
}

/* ---- Migracao: os produtos que ja foram digitados ----
   Um banco de itens que comeca vazio, com estudos ja digitados atras, nao e
   identidade: e uma segunda planilha. O catalogo so vale se reconhecer o passado.

   A varredura PROPOE e a pessoa confirma. Ligar sozinho seria adivinhar que
   "Sankari" e "Sankari 500" sao o mesmo produto — e quando erra, erra calado,
   dentro de um estudo que ja foi a campo. */
var _migAberta=false, _migResumo=null, _migPendentes=0;

function migracaoAbrir(){
  _migAberta=true; _itemAberto=null; _migResumo=migracaoCandidatos();
  var o=_itOvl(); o.style.display='flex'; _itensPinta();
}
function migracaoVoltar(){ _migAberta=false; _migResumo=null; _itensPinta(); }
function _migracaoRecarrega(){
  _migResumo=migracaoCandidatos();
  _migPendentes=_migResumo.ligaveis;
  _itensPinta();
}

function migracaoAcaoCriar(chave){
  var c=((_migResumo||{}).candidatos||[]).filter(function(x){ return x.chave===chave; })[0];
  if(!c) return;
  var r=migracaoCriarELigar(chave, c.nome, {});
  if(r.erro){ alert(r.erro); return; }
  _migracaoRecarrega();
  if(typeof _stxToast==='function') _stxToast('✓ "'+c.nome+'" cadastrado · '+r.ligados+' aberto'+(r.ligados===1?'':'s')+
    (r.historicos?(' · '+r.historicos+' histórico'+(r.historicos===1?'':'s')):''));
}
function migracaoAcaoLigar(chave, sel){
  var itemId=(sel&&sel.value)||'';
  if(!itemId) return;
  var r=migracaoLigar(chave, itemId);
  if(r.erro){ alert(r.erro); return; }
  _migracaoRecarrega();
  if(typeof _stxToast==='function') _stxToast('✓ '+r.ligados+' tratamento'+(r.ligados===1?'':'s')+' aberto'+(r.ligados===1?'':'s')+
    (r.historicos?(' · '+r.historicos+' vínculo'+(r.historicos===1?'':'s')+' histórico'+(r.historicos===1?'':'s')):''));
}

function _migracaoHtml(){
  var r=_migResumo||{candidatos:[], finalizados:0, ligaveis:0};
  var h='<div class="it-box"><div class="it-top"><div class="it-t">🔗 Produtos ja digitados</div>'+
        '<button class="it-x" onclick="fecharItens()" aria-label="Fechar">&times;</button></div>';
  h+='<button class="it-btn alt" onclick="migracaoVoltar()">&lsaquo; Banco de itens</button><div style="height:10px"></div>';

  if(!r.candidatos.length){
    h+='<div class="it-vazio">Nenhum produto digitado solto: todos os tratamentos já têm item, receita ou vínculo histórico confirmado.</div></div>';
    return h;
  }

  h+='<div class="it-dup" style="border-color:rgba(120,170,215,.3);color:#cfe0ef">'+
     'Estes nomes foram digitados a mao nos estudos. Cadastrar cada um <b>uma vez</b> faz o'+
     ' produto virar identidade: a partir dai a dose, o registro e o historico andam junto com ele.'+
     ' Nada e ligado sozinho — voce confirma cada um.'+
     (r.finalizados?('<br><br>'+r.finalizados+' ocorrência'+(r.finalizados===1?'':'s')+
       ' está em estudo finalizado. Ao confirmar, o Agracta cria um <b>vínculo histórico externo</b>: o estudo assinado não é alterado, mas passa a entrar no histórico e na matriz do item.'):'')+
     '</div>';

  var outros=(typeof itensLista==='function')?itensLista():[];

  r.candidatos.forEach(function(c){
    var pode=(c.simples+c.finalizadosSimples)>0;
    h+='<div class="it-lin" style="display:block;cursor:default">';
    h+='<div class="it-nome">'+esc(c.nome)+'</div>';

    var uso=c.ocorrencias+' uso'+(c.ocorrencias===1?'':'s')+' em '+c.nEstudos+' estudo'+(c.nEstudos===1?'':'s');
    h+='<div class="it-sub">'+esc(uso)+
       (c.grafias.length>1?(' &middot; escrito tambem como '+esc(c.grafias.slice(1).join(', '))):'')+'</div>';

    if(c.finalizadosSimples){
      h+='<div class="it-sub" style="color:#7ca88a">'+c.finalizadosSimples+' uso'+(c.finalizadosSimples===1?'':'s')+
         ' finalizado'+(c.finalizadosSimples===1?'':'s')+' será'+(c.finalizadosSimples===1?'':'ão')+
         ' conciliado'+(c.finalizadosSimples===1?'':'s')+' externamente, sem reescrever o estudo.</div>';
    }

    /* O numero precisa ser honesto ANTES do clique: o que esta dentro de mistura
       nao vai ser ligado por aqui, e prometer o contrario seria mentir na tela. */
    if(c.emMistura){
      h+='<div class="it-sub" style="color:#d8b26a">'+c.emMistura+' desse'+(c.emMistura===1?'':'s')+
         ' uso'+(c.emMistura===1?'':'s')+' esta dentro de uma mistura (ex.: "A + B"). '+
         (pode?('Serao ligados '+c.simples+', e a mistura continua como esta ate virar receita.')
              :'Nenhum pode ser ligado por aqui: monte a receita no tratamento, para o adjuvante nao se perder.')+
         '</div>';
    }
    if(c.finalizadosMistura){
      h+='<div class="it-sub" style="color:#d8b26a">'+c.finalizadosMistura+' ocorrência'+(c.finalizadosMistura===1?'':'s')+
         ' finalizada'+(c.finalizadosMistura===1?'':'s')+' está'+(c.finalizadosMistura===1?'':'ão')+
         ' dentro de mistura e precisa ser conciliada como receita, componente por componente.</div>';
    }

    if(c.sugestoes && c.sugestoes.length){
      h+='<div class="it-sub" style="color:#8fb6d8">Ja existe algo parecido no banco: '+
         esc(c.sugestoes.map(function(x){ return x.nome; }).join(', '))+'</div>';
    }

    if(pode){
      h+='<div class="it-row" style="margin-top:8px;align-items:center">'+
         '<button class="it-btn" onclick="migracaoAcaoCriar(\''+esc(c.chave)+'\')">+ Cadastrar &quot;'+esc(c.nome)+'&quot; e ligar</button>';
      if(outros.length){
        h+='<select class="it-busca" style="margin:0" onchange="migracaoAcaoLigar(\''+esc(c.chave)+'\',this)">'+
           '<option value="">ou ligar a um item existente…</option>';
        outros.forEach(function(it){
          h+='<option value="'+esc(it.id)+'">'+esc(it.nome||'(sem nome)')+(it.codigo?(' · '+esc(it.codigo)):'')+'</option>';
        });
        h+='</select>';
      }
      h+='</div>';
    }
    h+='</div>';
  });

  h+='</div>';
  return h;
}

/* A matriz na tela. Ela vem ANTES da lista de usos porque responde a pergunta que
   se faz primeiro: "em que doses isso ja foi testado?". A lista continua embaixo,
   porque as vezes a pergunta e "em qual estudo, mesmo?". */
function _itemMatrizHtml(itemId){
  var m=itemMatrizDose(itemId);
  if(!m.blocos.length && !m.naoLidas.length) return '';
  var h='<div class="it-t" style="font-size:13px;margin:14px 0 6px">Doses ja testadas</div>';

  /* Duas familias de dose no mesmo item nao formam uma escada. Dizer isso e o ponto
     do relatorio: sem o aviso, alguem le "0,4 a 1000" como uma faixa. */
  if(!m.comparavel){
    h+='<div class="it-dup">Este item foi usado em <b>escalas diferentes</b> ('+
       esc(m.blocos.map(function(b){ return b.rotulo; }).join(' e '))+
       '). Elas nao se convertem uma na outra sem um numero que aqui nao existe, entao'+
       ' aparecem separadas — comparar dose entre elas seria inventar uma serie que nao existe.</div>';
  }

  m.blocos.forEach(function(b){
    if(m.blocos.length>1) h+='<div class="it-sub" style="margin:8px 0 4px;font-weight:800;color:#8fb6d8">Dose '+esc(b.rotulo)+'</div>';
    b.linhas.forEach(function(ln){
      var det=[ln.nEstudos+' estudo'+(ln.nEstudos===1?'':'s')];
      if(ln.culturasLista.length) det.push(ln.culturasLista.join(', '));
      if(ln.finalizados) det.push(ln.finalizados+' finalizado'+(ln.finalizados===1?'':'s'));
      h+='<div class="it-dose"><div><b>'+esc(ln.texto)+'</b>'+
         /* Grafias diferentes da MESMA dose ficam visiveis: e assim que se descobre
            que a equipe escreve "0,4 L/ha" e "400 mL/ha" para a mesma coisa. */
         (ln.grafiasLista.length>1?(' <span style="opacity:.6;font-weight:600">tambem escrita '+esc(ln.grafiasLista.slice(1).join(', '))+'</span>'):'')+
         '<div class="it-sub">'+esc(det.join(' · '))+'</div></div>'+
         '<span class="it-tag">'+ln.nUsos+'&times;</span></div>';
    });
  });

  if(m.naoLidas.length){
    /* Nunca some com o que nao foi lido: um numero que desaparece do relatorio e
       pior do que um numero que aparece marcado como ilegivel. */
    var motivos={};
    m.naoLidas.forEach(function(x){ motivos[x.motivo]=(motivos[x.motivo]||0)+1; });
    h+='<div class="it-sub" style="margin-top:8px;color:#d8b26a">'+m.naoLidas.length+' uso'+
       (m.naoLidas.length===1?'':'s')+' fora da matriz: '+
       esc(Object.keys(motivos).map(function(k){ return motivos[k]+' com '+k; }).join('; '))+'.</div>';
  }
  return h;
}

