function itemCampo(id, campo, v){
  var val=String(v||'').trim();
  if(campo==='nome'&&!val){ alert('O item precisa ter um nome.'); _itensPinta(); return; }
  itemAtualizar(id, (function(){ var o={}; o[campo]=val; return o; })()); _itensPinta();
}
function itemDoseFora(id, doseId){ itemDoseAposentar(id, doseId); _itensPinta(); }
function itemApagar(id){
  var it=itemPorId(id); if(!it) return;
  var usos=itemOndeFoiUsado(id);
  if(usos.length){ alert('Este item está em '+usos.length+' tratamento(s) de estudo. Excluí-lo deixaria esses tratamentos sem identidade.\n\nDesligue-o desses tratamentos antes, ou marque a situação como "Cancelado".'); return; }
  if(!confirm('Excluir "'+(it.nome||id)+'" do banco de itens?')) return;
  itemExcluir(id); _itemAberto=null; _itensPinta();
}
function itemDoseNova(id){
  function v(x){ var el=document.getElementById(x); return el?String(el.value||'').trim():''; }
  if(!v('dsValor')){ alert('Informe a dose.'); return; }
  var r=itemDoseAdicionar(id, {cultura:v('dsCultura'), alvo:v('dsAlvo'), valor:v('dsValor'),
    valorMax:v('dsValorMax'), unidade:v('dsUnidade')||'L/ha',
    origem:v('dsOrigem')||'manual', documento:v('dsDoc')});
  if(!r||r.erro){ alert((r&&r.erro)||'Não foi possível adicionar a dose.'); return; }
  _itensPinta();
}
function itemLoteAbrir(loteId){ _loteAberto=loteId; _itensPinta(); }
function itemLoteVoltar(){ _loteAberto=null; _itensPinta(); }
function _itemCampoValor(id){var e=document.getElementById(id);return e?String(e.value||'').trim():'';}
function itemLoteNovoUI(itemId){
  var r=itemLoteNovo(itemId,{codigo:_itemCampoValor('ltCodigo'),recebidoEm:_itemCampoValor('ltRecebido'),
    quantidade:_itemCampoValor('ltQtd'),unidade:_itemCampoValor('ltUnidade'),validade:_itemCampoValor('ltValidade'),
    fornecedor:_itemCampoValor('ltFornecedor'),documento:_itemCampoValor('ltDocumento'),
    armazenamento:_itemCampoValor('ltArmazenamento')});
  if(!r||r.erro){alert((r&&r.erro)||'Não foi possível cadastrar o lote.');return;}
  _loteAberto=r.id;_itensPinta();
}
function itemLoteEventoUI(itemId,loteId){
  var tipo=_itemCampoValor('ltEvTipo'),destino=_itemCampoValor('ltEvDestino');
  var r=itemLoteEvento(itemId,loteId,{tipo:tipo,quantidade:_itemCampoValor('ltEvQtd'),
    em:_itemCampoValor('ltEvData'),documento:_itemCampoValor('ltEvDoc'),
    origem:(tipo==='entrada'?destino:''),destino:(tipo==='entrada'?'':destino),
    estudoId:_itemCampoValor('ltEvEstudo'),tratamentoId:_itemCampoValor('ltEvTrat'),obs:_itemCampoValor('ltEvObs')});
  if(!r||r.erro){alert((r&&r.erro)||'Não foi possível registrar o evento.');return;}
  _itensPinta();
}

/* ---- Ligação com o tratamento ----
   O tratamento continua tendo t.produto (texto) porque trinta e tantos estudos já
   existem com ele preenchido, e apagá-los para "modernizar" seria destruir dado real.
   O que entra é t.itemId ao lado: quando existe, MANDA; quando não, o texto continua
   valendo exatamente como sempre valeu.

   É essa convivência que permite migrar sem migração — o estudo antigo segue
   funcionando, e o novo ganha identidade. */
function tratItem(t){ return (t&&t.itemId)?itemPorId(t.itemId):null; }

/* O nome que aparece na tela. Item ligado manda; senão, o texto digitado. E código
   cego, quando existe, esconde a identidade de quem não deve vê-la. */
function tratProdutoNome(t, revelar){
  var it=tratItem(t);
  if(!it) return (t&&t.produto)||'';
  if(it.codigoCego && !revelar) return it.codigoCego;
  return it.nome||((t&&t.produto)||'');
}

/* Liga um tratamento a um item do catálogo. Guarda o texto original em
   produtoOriginal: se alguém ligou ao item errado, o que estava escrito no protocolo
   não se perdeu. */
function tratLigarItem(t, itemId, doseId){
  if(!t) return null;
  var it=itemPorId(itemId); if(!it) return null;
  if(t.itemId && t.itemId!==it.id) delete t.loteRef;
  if(t.produto && !t.produtoOriginal) t.produtoOriginal=t.produto;
  t.itemId=it.id;
  t.produto=it.nome||t.produto;
  if(doseId){
    var d=(itemDoses(it.id)||[]).filter(function(x){ return x.id===doseId; })[0];
    if(d){
      /* SNAPSHOT. A dose vai COPIADA para o tratamento, não referenciada: se a bula
         mudar no ano que vem, o ensaio antigo tem de continuar dizendo o que ele
         realmente usou. Referência viva reescreveria a história. */
      t.dose=(d.valor!=null?String(d.valor).replace('.',','):'')+(d.unidade?(' '+d.unidade):'');
      t.doseRef={
        itemId:it.id, doseId:d.id, cultura:d.cultura, alvo:d.alvo,
        valor:d.valor, valorMax:d.valorMax, unidade:d.unidade,
        origem:d.origem, documento:d.documento, pagina:d.pagina,
        congeladoEm:Date.now()
      };
    }
  }
  return t;
}
function tratDesligarItem(t){
  if(!t) return;
  delete t.itemId; delete t.doseRef; delete t.loteRef;
  if(t.produtoOriginal){ t.produto=t.produtoOriginal; delete t.produtoOriginal; }
}
function tratLigarLote(t,loteId){
  if(!t||!t.itemId) return null;
  if(!loteId){ delete t.loteRef; return t; }
  var lote=itemLotePorId(t.itemId,loteId); if(!lote) return null;
  t.loteRef={itemId:t.itemId,loteId:lote.id,codigo:lote.codigo,unidade:lote.unidade,
             selecionadoEm:Date.now()};
  return t;
}

/* A dose escolhida bate com o que a bula registra? Não bloqueia — ensaio
   experimental existe para sair da bula. Mas marca, e pede justificativa. */
function tratDoseForaDaBula(t){
  var r=t&&t.doseRef; if(!r || r.origem!=='bula') return false;
  var v=_calcNum(t.dose);
  if(!(v>0)) return false;
  var min=(r.valor!=null&&isFinite(r.valor))?r.valor:null;
  var max=(r.valorMax!=null&&isFinite(r.valorMax))?r.valorMax:min;
  if(min==null) return false;
  return (v<min-1e-9 || v>max+1e-9);
}

/* Onde mais este item foi testado. É a pergunta que o catálogo veio permitir, e ela
   só é respondível porque o item tem ID — com texto livre, "Sankari" e "SANKARI
   500 SC" nunca se encontrariam. */
/* ---- Matriz Item x Dose ----
   "Onde foi usado" e uma lista; a pergunta de pesquisa e outra: EM QUE DOSES este
   item ja foi testado, e quantas vezes cada uma. So da para responder isso agora
   porque o item virou identidade — antes, "Sankari" e "sankari" eram dois produtos.

   A regra dura vem do motor de doses: 0,4 L/ha e 400 mL/ha sao a MESMA dose e tem
   de cair na mesma linha; 0,4 L/ha e 2 mL/L NAO sao comparaveis e nao podem cair na
   mesma escada. Empilhar as duas num grafico bonito seria inventar uma serie que
   nao existe. */

/* Le a dose como ela foi ESCRITA. _calcDoseUnit() forca tudo para unidade por area
   — o que serve ao calculo de calda de campo, mas aqui leria "2 mL/L" (concentracao
   na calda) como "2 mL/ha" (dose por hectare): coisas diferentes por tres ordens de
   grandeza. Aqui "nao sei qual e a unidade" e uma resposta valida, e melhor do que
   um palpite. */
function _doseLer(raw){
  var DC=window.DoseCore; if(!DC) return null;
  var s=String(raw==null?'':raw).trim();
  if(!s) return null;
  var val=_calcNum(s);
  if(!(val>0)) return null;
  var norm=s.toLowerCase().replace(/\s+/g,'');
  /* Da unidade mais longa para a mais curta: senao "mL/ha" seria capturado por
     "L/ha" e "% v/v" viraria outra coisa. */
  var us=DC.unidades().slice().sort(function(a,b){ return b.length-a.length; });
  var achada=null;
  for(var i=0;i<us.length;i++){
    if(norm.indexOf(us[i].toLowerCase().replace(/\s+/g,''))>=0){ achada=us[i]; break; }
  }
  if(!achada) return null;
  var c=DC.canonico(val, achada);
  if(!c) return null;
  return {valor:val, unidade:achada, canonico:c, alvo:(DC.UNIDADES[achada].alvo||null)};
}

/* Por que uma dose nao entrou na matriz. Dizer "nao entendi" e pior do que dizer o
   que falta: com o motivo, a pessoa corrige o dado. */
function _doseMotivo(raw){
  var s=String(raw==null?'':raw).trim();
  if(!s) return 'sem dose registrada';
  if(!(_calcNum(s)>0)) return 'sem numero legivel';
  if(/%/.test(s)) return '"%" sozinho nao diz se e v/v (volume) ou m/v (massa) — sao doses diferentes';
  return 'unidade nao reconhecida';
}

function itemMatrizDose(itemId){
  var DC=window.DoseCore;
  var usos=(typeof itemOndeFoiUsado==='function')?itemOndeFoiUsado(itemId):[];
  var blocos={}, naoLidas=[];

  usos.forEach(function(u){
    var d=DC?_doseLer(u.dose):null;
    if(!d){ naoLidas.push({uso:u, motivo:_doseMotivo(u.dose)}); return; }
    /* "planta", "placa" e "vaso" compartilham a base mL/alvo, mas uma planta nao e
       uma placa: o alvo entra na chave, senao dose de casa de vegetacao se somaria
       com dose de bancada. */
    var bk=d.canonico.unidade+'@'+(d.alvo||'-');
    if(!blocos[bk]) blocos[bk]={chave:bk, familia:d.canonico.familia, base:d.canonico.unidade,
                                alvo:d.alvo, linhas:{}, usos:0};
    var b=blocos[bk];
    b.usos++;
    var lk=d.canonico.valor.toFixed(6);
    if(!b.linhas[lk]) b.linhas[lk]={valor:d.canonico.valor, base:d.canonico.unidade,
                                    grafias:{}, usos:[], estudos:{}, culturas:{}, finalizados:0};
    var ln=b.linhas[lk];
    ln.grafias[String(u.dose||'').trim()]=(ln.grafias[String(u.dose||'').trim()]||0)+1;
    ln.usos.push(u);
    ln.estudos[u.estudoId]=1;
    if(u.cultura) ln.culturas[u.cultura]=1;
    if(u.finalizado) ln.finalizados++;
  });

  var out=Object.keys(blocos).map(function(bk){
    var b=blocos[bk];
    b.linhas=Object.keys(b.linhas).map(function(lk){
      var ln=b.linhas[lk];
      var gs=Object.keys(ln.grafias).sort(function(a,c){ return ln.grafias[c]-ln.grafias[a]; });
      ln.texto=gs[0]||DC.formatar(ln.valor, ln.base);
      ln.grafiasLista=gs;
      ln.nUsos=ln.usos.length;
      ln.nEstudos=Object.keys(ln.estudos).length;
      ln.culturasLista=Object.keys(ln.culturas);
      return ln;
    }).sort(function(a,c){ return a.valor-c.valor; });   /* a escada, de baixo para cima */
    b.rotulo=(b.alvo?('por '+b.alvo):(b.familia==='area'?'por area':(b.familia==='calda'?'na calda':b.familia)));
    return b;
  }).sort(function(a,c){ return c.usos-a.usos; });

  return {blocos:out, naoLidas:naoLidas,
          /* Mais de um bloco significa que NAO existe uma escada unica. Quem ler o
             relatorio precisa saber disso antes de comparar dose com dose. */
          comparavel:(out.length<=1),
          nUsos:usos.length};
}

function itemOndeFoiUsado(itemId){
  var out=[],vistos={};
  if(typeof data==='undefined'||!data) return out;
  function incluir(u,chave){ if(vistos[chave])return; vistos[chave]=1; out.push(u); }
  Object.keys(data).forEach(function(qid){
    if(qid==='__config') return;
    ((data[qid]||{}).estudos||[]).forEach(function(st){
      (st.tratamentos||[]).forEach(function(t){
        if(!t) return;
        var base={qid:qid, quadra:(typeof quadraNome==='function'?quadraNome(qid):qid),
                  estudoId:st.id, estudo:(st.codigo||st.nome||st.id),
                  cultura:(typeof studyCultura==='function'?studyCultura(st,data[qid]||{}):''),
                  tratamento:t.id,
                  finalizado:(typeof estudoFinalizado==='function'?!!estudoFinalizado(st):false)};
        var cs=Array.isArray(t.componentes)?t.componentes:[];
        /* Receita estruturada manda sobre o item simples possivelmente deixado por
           uma versão antiga do editor. Cada componente leva SUA dose; usar t.dose
           aqui produziria "0,8 L/ha + 0,1 %" como se fosse a dose do adjuvante. */
        if(cs.length){
          cs.forEach(function(c){
            if(!c||c.itemId!==itemId)return;
            var dose=(c.valor!=null?String(c.valor).replace('.',','):'')+(c.unidade?(' '+c.unidade):'');
            incluir(Object.assign({},base,{dose:dose,origem:((c.doseRef&&c.doseRef.origem)||null),
              componente:(c.nome||''),componenteId:c.id,lote:((c.loteRef&&c.loteRef.codigo)||'')}),
              [qid,st.id,t.id,c.id||c.itemId].join('|'));
          });
        }else if(t.itemId===itemId){
          incluir(Object.assign({},base,{dose:(t.dose||''),origem:((t.doseRef&&t.doseRef.origem)||null),
            lote:((t.loteRef&&t.loteRef.codigo)||'')}),[qid,st.id,t.id,''].join('|'));
        }
      });
    });
  });
  /* Estudos finalizados conciliados externamente entram no mesmo relatório, sem
     que uma única propriedade do tratamento assinado tenha sido alterada. */
  var historicos=(typeof itemVinculosHistoricos==='function')?itemVinculosHistoricos(itemId):[];
  historicos.forEach(function(v){
    incluir({qid:v.qid,quadra:v.quadra||v.qid,estudoId:v.estudoId,estudo:v.estudo||v.estudoId,
      cultura:v.cultura||'',tratamento:v.tratamentoId,dose:v.dose||'',origem:v.origem||'historica',
      finalizado:true,historico:true,produtoOriginal:v.produtoOriginal||''},
      [v.qid,v.estudoId,v.tratamentoId,v.componenteId||''].join('|'));
  });
  return out;
}

/* ===================== DOIS AVALIADORES (roadmap §10) ============================
   Severidade de doença, nota de fitotoxicidade, escala de dano: são leituras humanas,
   e leitura humana varia. Dois avaliadores olhando a mesma parcela dão números
   diferentes — e a pergunta de um ensaio sob BPL não é "qual dos dois está certo", é
   "o quanto eles concordam, e o que isso faz com o resultado".

   A LEITURA É CEGA, DE VERDADE. Enquanto A avalia, os valores de B não são
   escurecidos nem escondidos por CSS: eles não são renderizados. Cegamento que se
   derrota rolando a tela ou abrindo o inspetor não é cegamento — é um enfeite que faz
   o estudo parecer mais rigoroso do que é, que é pior que não ter.

   O VALOR CONSOLIDADO É A MÉDIA DOS DOIS, e vai marcado como derivado. Ele é o que
   alimenta a estatística, o gráfico e a AACPD; as duas leituras originais ficam
   guardadas, porque é delas que sai a concordância e é a elas que se volta quando
   alguém contesta um número três anos depois. ==================================== */

var AV_AVALIADORES=['A','B'];

function avDupla(av){ return !!(av && av.duplaLeitura); }
function avAvaliadores(av){
  if(!av) return null;
  if(!av.avaliadores) av.avaliadores={};
  AV_AVALIADORES.forEach(function(k){
    if(!av.avaliadores[k]) av.avaliadores[k]={nome:'', notas:{}};
    if(!av.avaliadores[k].notas) av.avaliadores[k].notas={};
  });
  return av.avaliadores;
}
/* Quem está com a prancheta agora. Vazio = visão consolidada, que só se abre depois
   de as duas leituras existirem. */
var _avQuem=null;
function avQuemAtivo(){ return _avQuem; }
function avSetQuem(k){ _avQuem=(AV_AVALIADORES.indexOf(k)>=0)?k:null; }

/* O mapa de notas que a grade deve mostrar E escrever. Com um avaliador ativo, é o
   dele e só o dele — é aqui que o cegamento acontece, na origem do dado, não na
   pintura. */
function avNotasVisiveis(av){
  if(!avDupla(av)) return (av&&av.notas)||{};
  var q=avQuemAtivo();
  if(!q) return (av&&av.notas)||{};
  return avAvaliadores(av)[q].notas;
}

/* Consolidação: média das duas leituras, parcela a parcela, variável a variável.
   Parcela que só um avaliou fica com o valor dele — descartá-la perderia dado real,
   e inventar a segunda leitura seria muito pior. O que ficou com uma leitura só vai
   contado, para o relatório poder dizer. */
function avConsolidar(av){
  if(!avDupla(av)) return null;
  var A=avAvaliadores(av).A.notas, B=avAvaliadores(av).B.notas;
  var out={}, so=0, dois=0;
  var chaves={};
  [A,B].forEach(function(m){ for(var k in m) chaves[k]=1; });
  for(var k in chaves){
    var ra=A[k]||{}, rb=B[k]||{}, vars={}, linha={};
    for(var v in ra) vars[v]=1;
    for(var v2 in rb) vars[v2]=1;
    for(var v3 in vars){
      var a=_avNum(ra[v3]), b=_avNum(rb[v3]);
      if(a!=null&&b!=null){ linha[v3]=Math.round(((a+b)/2)*1000)/1000; dois++; }
      else if(a!=null){ linha[v3]=a; so++; }
      else if(b!=null){ linha[v3]=b; so++; }
    }
    if(Object.keys(linha).length) out[k]=linha;
  }
  av.notas=out;
  av.notasOrigem={tipo:'media-dois-avaliadores', comDuas:dois, comUma:so, em:Date.now()};
  return av.notasOrigem;
}
function _avNum(v){
  if(v===''||v==null) return null;
  var n=(typeof v==='number')?v:Number(String(v).replace(',','.'));
  return isFinite(n)?n:null;
}

/* Escala da variável, do tipo que o estudo já declarou. Nota de classe é ORDINAL e
   pede kappa; severidade em % e contagem são contínuas e pedem ICC. Adivinhar isso
   pelos valores daria kappa em severidade, que não significa nada. */
function avEscalaDaVariavel(av, v){
  var t=(av&&av.tipos&&av.tipos[v])||'pct';
  return (t==='escala')?'ordinal':'continua';
}

/* A concordância de uma variável. Delegada ao motor puro; aqui só se junta o que a
   avaliação sabe. */
/* ---- Controles na tela ---- */

/* Ligar/desligar a leitura dupla. Desligar NÃO apaga o que os dois já leram: o dado
   fica guardado e volta se religar. Apagar leitura de campo por causa de um toque
   numa chave seria imperdoável. */
function avToggleDupla(){
  var av=_avEditando(); if(!av) return;
  av.duplaLeitura=!av.duplaLeitura;
  if(av.duplaLeitura){
    avAvaliadores(av);
    /* A primeira leitura já feita vira a de A: ela existe e é de alguém. */
    if(!Object.keys(av.avaliadores.A.notas).length && av.notas && Object.keys(av.notas).length){
      av.avaliadores.A.notas=JSON.parse(JSON.stringify(av.notas));
    }
    avSetQuem('A');
  }else{
    avSetQuem(null);
  }
  try{ save(); }catch(e){}
  openStudyEditAvaliacao(av.id);
}
function avTrocarQuem(k){
  var av=_avEditando(); if(!av) return;
  /* Salva o que está na tela ANTES de trocar, senão a leitura de A se perde ao
     passar a prancheta para B. */
  try{ _avSyncInputs(); }catch(e){}
  var atual=avQuemAtivo();
  if(atual && avDupla(av)){ avAvaliadores(av)[atual].notas=JSON.parse(JSON.stringify(_avGrid.notas||{})); avConsolidar(av); try{ save(); }catch(e){} }
  avSetQuem(k);
  openStudyEditAvaliacao(av.id);
}
function avNomeAvaliador(k, nome){
  var av=_avEditando(); if(!av) return;
  avAvaliadores(av)[k].nome=String(nome||'').trim();
  try{ save(); }catch(e){}
}
function _avEditando(){
  var q=data[curV]||{}, st=(q.estudos||[]).filter(function(s){return s.id===curSid;})[0];
  if(!st) return null;
  return (st.avaliacoes||[]).filter(function(a){return a.id===editingAvId;})[0]||null;
}

/* O bloco na tela da avaliação. Fora da leitura dupla é uma linha só; dentro, a
   troca de prancheta e a concordância. */
function avDuplaHtml(study, av){
  if(!av) return '';
  var h='<div class="se-section-title">Leitura</div>';
  if(!avDupla(av)){
    return h+'<div class="se-field"><label style="display:flex;align-items:center;gap:8px;text-transform:none;letter-spacing:0;color:#c8d8c8;font-size:13px">'+
      '<input type="checkbox" onchange="avToggleDupla()" style="width:auto"> Leitura dupla (dois avaliadores)</label>'+
      '<div class="e-hint">Dois avaliadores leem as mesmas parcelas sem ver a leitura um do outro. No fim, o app mostra o quanto concordaram e usa a média dos dois.</div></div>';
  }
  var ad=avAvaliadores(av), q=avQuemAtivo()||'A';
  h+='<div class="se-field"><label style="display:flex;align-items:center;gap:8px;text-transform:none;letter-spacing:0;color:#c8d8c8;font-size:13px">'+
     '<input type="checkbox" checked onchange="avToggleDupla()" style="width:auto"> Leitura dupla (dois avaliadores)</label></div>';
  h+='<div class="av-dupla">';
  AV_AVALIADORES.forEach(function(k){
    var n=Object.keys(ad[k].notas||{}).length;
    h+='<button type="button" class="av-quem'+(k===q?' on':'')+'" onclick="avTrocarQuem(\''+k+'\')">'+
       k+(ad[k].nome?(' · '+esc(ad[k].nome)):'')+'<i>'+(n?(n+' parcela'+(n===1?'':'s')):'sem leitura')+'</i></button>';
  });
  h+='</div>';
  h+='<div class="se-row">';
  AV_AVALIADORES.forEach(function(k){
    h+='<div class="se-field"><label>Nome do avaliador '+k+'</label>'+
       '<input type="text" value="'+esc(ad[k].nome||'')+'" onchange="avNomeAvaliador(\''+k+'\',this.value)" placeholder="quem leu"></div>';
  });
  h+='</div>';
  h+='<div class="e-hint">A grade abaixo é a leitura de <b>'+esc(q+(ad[q].nome?(' · '+ad[q].nome):''))+'</b>. '+
     'A leitura do outro avaliador não é carregada nesta tela — é assim que a leitura fica cega de verdade.</div>';

  /* Concordância: só quando há as duas leituras. Antes disso não há o que comparar,
     e mostrar o quadro vazio sugeriria que faltou calcular. */
  var temA=Object.keys(ad.A.notas||{}).length, temB=Object.keys(ad.B.notas||{}).length;
  if(temA && temB){
    h+='<div class="av-conc"><div class="av-conc-t">CONCORDÂNCIA ENTRE OS AVALIADORES</div>';
    (av.variaveis||[]).forEach(function(v){
      var r=avConcordancia(study, av, v);
      if(!r || r.erro){ h+='<div class="av-conc-l"><b>'+esc(v)+'</b> — '+esc((r&&r.erro)||'sem cálculo')+'</div>'; return; }
      h+='<div class="av-conc-l"><b>'+esc(v)+'</b> ('+esc(r.escala)+', '+r.n+' parcela'+(r.n===1?'':'s')+')</div>';
      (r.leitura||[]).forEach(function(t){ h+='<div class="av-conc-v">'+esc(t)+'</div>'; });
      (r.avisos||[]).forEach(function(t){ h+='<div class="av-conc-a">⚠ '+esc(t)+'</div>'; });
    });
    h+='<div class="e-hint" style="margin:6px 0 0">O valor que vai para a estatística é a <b>média dos dois</b>. As duas leituras originais ficam guardadas — é delas que sai este quadro.</div>';
    h+='</div>';
  }
  return h;
}

function avConcordancia(study, av, v){
  var C=(typeof window!=='undefined')?window.ConcordanciaCore:null;
  if(!C) return {erro:'O motor de concordância não carregou. Recarregue o app.'};
  if(!avDupla(av)) return {erro:'Esta avaliação não está em leitura dupla.'};
  var ad=avAvaliadores(av);
  var linhas=(typeof _avRowsForStudy==='function')?_avRowsForStudy(study,false):[];
  var chaves=linhas.map(function(r){ return r.key; });
  function so(mapa){ var o={}; chaves.forEach(function(k){ o[k]=(mapa[k]||{})[v]; }); return o; }
  var r=C.concordancia(so(ad.A.notas), so(ad.B.notas), chaves,
                       {escala:avEscalaDaVariavel(av,v)});
  r.variavel=v;
  r.nomeA=(ad.A.nome||'Avaliador A');
  r.nomeB=(ad.B.nome||'Avaliador B');
  return r;
}

/* ===================== JANELA AMBIENTAL (roadmap §9) =============================
   O carimbo guarda o INSTANTE de cada evento: fazia 26 °C e 60% de UR quando se
   aplicou. Isso responde "em que condição foi aplicado" e não responde a outra
   pergunta, que é a que explica o resultado do ensaio:

       o que aconteceu ENTRE a aplicação e esta avaliação?

   Choveu 72 mm dois dias depois da aplicação? Passou de 31 °C na semana do
   florescimento? Ficou quinze dias sem chuva? É isso que separa "o produto não
   funcionou" de "o produto foi lavado", e nenhum instante isolado diz.

   A janela vai GRAVADA na avaliação, não recalculada a cada abertura. Duas razões:
   a leitura de uma estação pode mudar quando a Ecowitt reprocessa, e o que vale num
   registro BPL é o que foi lido quando se registrou; e a avaliação precisa poder ser
   lida offline, no campo, sem rede.

   COBERTURA VAI JUNTO, SEMPRE. Uma média de 11 dias apresentada como "os 14 dias da
   janela" é mentira — e é o tipo de mentira que passa despercebida porque o número
   parece limpo. ================================================================== */

var _janelaSeq=0, _janelaEstado={};   /* chave -> 'buscando' | 'erro' | null */

/* A aplicação que precede esta avaliação. É dela que a janela parte: o intervalo que
   interessa é o que o tratamento passou exposto, não o calendário inteiro do estudo. */
function janelaAplicacaoAnterior(study, av){
  if(!study||!av||!av.data) return null;
  var antes=(study.aplicacoes||[]).filter(function(a){ return a.data && a.data<=av.data; })
    .sort(function(a,b){ return String(a.data).localeCompare(String(b.data)); });
  return antes.length?antes[antes.length-1]:null;
}

function janelaDaAvaliacao(av){ return (av&&av.janela)||null; }
function _janelaChave(qid, sid, avid){ return qid+'|'+sid+'|'+avid; }

/* Busca e grava. Só grava se ainda não houver — uma janela regravada depois mudaria
   o registro do que foi lido no dia, que é justamente o que ele existe para guardar.
   `forcar` é para o botão de reconsultar, e aí a anterior vira histórico. */
function consultarJanela(qid, sid, av, forcar, cb){
  cb=cb||function(){};
  var study=(data[qid]&&(data[qid].estudos||[]).filter(function(s){return s.id===sid;})[0])||null;
  if(!study||!av||!av.data){ cb(null); return; }
  if(av.janela && !forcar){ cb(av.janela); return; }

  var ap=janelaAplicacaoAnterior(study, av);
  if(!ap){ cb({erro:'Esta avaliação não tem aplicação anterior no estudo — sem ponto de partida para a janela.'}); return; }
  if(ap.data===av.data){ cb({erro:'A avaliação é do mesmo dia da aplicação: não há intervalo a resumir.'}); return; }

  var mac=(typeof _stationMacForQuadra==='function')?_stationMacForQuadra(qid):null;
  if(!mac){ cb({erro:'Esta quadra não tem estação meteorológica associada.'}); return; }

  var chave=_janelaChave(qid,sid,av.id), seq=++_janelaSeq;
  _janelaEstado[chave]='buscando';
  var url=NDVI_PROXY+'/clima/janela?mac='+encodeURIComponent(mac)+
          '&de='+encodeURIComponent(ap.data)+'&ate='+encodeURIComponent(av.data);
  fetch(url).then(function(r){ return r.json(); }).then(function(d){
    if(seq!==_janelaSeq && _janelaEstado[chave]!=='buscando') return;
    if(!d || d.error){ _janelaEstado[chave]='erro'; cb({erro:(d&&d.error)||'Não consegui montar a janela.'}); return; }
    _janelaEstado[chave]=null;
    var j={
      de:ap.data, ate:av.data, aplicacao:ap.id,
      dias:d.dias, diasComLeitura:d.dias_com_leitura, coberturaPct:d.cobertura_pct,
      diasSemLeitura:(d.dias_sem_leitura||[]),
      chuvaMm:d.chuva_mm, diasComChuva:d.dias_com_chuva,
      tempMedia:d.temp_media, tempMax:d.temp_max, tempMin:d.temp_min,
      urMedia:d.ur_media, ventoMedio:d.vento_medio, rajadaMax:d.rajada_max,
      radiacaoMedia:d.radiacao_media,
      fonte:d.fonte, mac:mac, ts:Date.now(), iso:new Date().toISOString(),
      app:(typeof APP_VER!=='undefined'?APP_VER:null)
    };
    /* Reconsultar não apaga: a leitura anterior vira histórico, como a memória de
       cálculo já faz. Uma janela refeita depois de a estação reprocessar é
       informação, não correção silenciosa. */
    if(av.janela){ av.janelasAnteriores=(av.janelasAnteriores||[]); av.janelasAnteriores.push(av.janela); }
    av.janela=j;
    av._ts=Date.now();
    try{ save(); }catch(e){}
    try{ if(typeof dbUpsertAvaliacao==='function') dbUpsertAvaliacao(qid,sid,av); }catch(e){}
    cb(j);
  }).catch(function(){
    _janelaEstado[chave]='erro';
    cb({erro:'Não consegui falar com o servidor de clima.'});
  });
}

/* Uma linha, do jeito que se lê em voz alta: "14 dias, 72 mm, média 24,6 °C..." */
function janelaResumo(j){
  if(!j||j.erro) return (j&&j.erro)||'';
  function n(v,d){ return (v==null||!isFinite(v))?null:String(Number(v).toFixed(d==null?1:d)).replace('.',','); }
  var p=[];
  p.push(j.dias+' dia'+(j.dias===1?'':'s'));
  if(n(j.chuvaMm)!=null) p.push(n(j.chuvaMm)+' mm');
  if(n(j.tempMedia)!=null) p.push('média '+n(j.tempMedia)+' °C');
  if(n(j.tempMax)!=null) p.push('máx '+n(j.tempMax)+' °C');
  if(j.diasComChuva!=null) p.push(j.diasComChuva+' dia'+(j.diasComChuva===1?'':'s')+' com chuva');
  return p.join(' · ');
}

/* A cobertura não é rodapé: quando a estação faltou, isso muda como se lê o número
   de cima. Por isso ela sai como frase, e não como percentual solto. */
function janelaCobertura(j){
  if(!j||j.erro) return '';
  if(j.coberturaPct>=100) return '';
  if(!j.diasComLeitura) return 'A estação não tinha leitura em nenhum dia desta janela — os valores acima não puderam ser calculados.';
  return 'Atenção: '+j.diasComLeitura+' de '+j.dias+' dias com leitura ('+j.coberturaPct+'%). '+
         'Os números acima descrevem só esses dias — a chuva dos '+(j.dias-j.diasComLeitura)+
         ' dias sem leitura não entra no total.';
}

/* ===================== NUTRIÇÃO — PONTE PARA O MOTOR ==============================
   A aritmética de calagem e recomendação mora em vendor/nutricao-core.js, extraída
   daqui sem uma linha alterada. O que ficou no app é o que depende do aparelho: ler o
   pacote de tabelas do localStorage e pintar a tela.

   Estas funções continuam existindo com os mesmos nomes porque a interface inteira as
   chama assim; elas apenas delegam. Reimplementar a conta aqui seria criar um segundo
   motor livre para divergir do primeiro — que é exatamente o erro que a memória de
   cálculo veio corrigir na calculadora. ============================================ */
function _nucleoNutricao(){
  var N=(typeof window!=='undefined')?window.NutricaoCore:null;
  if(!N) throw new Error('O motor de nutrição (NutricaoCore) não carregou. Recarregue o app.');
  return N;
}
function soloIndices(res){ return _nucleoNutricao().soloIndices(res); }
/* O pacote é a única coisa que o motor não busca sozinho: ele mora no aparelho. */

/* ----- Calagem pelo método da saturação por bases -----
   NC (t/ha) = (V2 − V1) × T / (10 × PRNT%)
   Fórmula agronômica publicada e reproduzida há décadas em material de extensão.
   O V2 (saturação desejada) depende da cultura e vem de tabela de recomendação —
   por isso ele é INFORMADO, não embutido: assim o cálculo funciona sem depender de
   nenhuma publicação, e quem tem a tabela licenciada usa o valor dela. */
function soloCalagem(res, V2, PRNT, profundidadeCm){
  var ind=soloIndices(res);
  V2=Number(V2); PRNT=Number(PRNT);
  if(ind.T==null||ind.V==null) return {erro:'Faltam Ca, Mg, K ou H+Al para calcular a CTC.'};
  if(!isFinite(V2)||V2<=0||V2>100) return {erro:'Informe a saturação por bases desejada (V2), de 1 a 100%.'};
  if(!isFinite(PRNT)||PRNT<=0||PRNT>100) return {erro:'Informe o PRNT do calcário, de 1 a 100%.'};
  if(V2<=ind.V) return {nc:0, V1:ind.V, V2:V2, T:ind.T, PRNT:PRNT,
                        nota:'A saturação atual já está em ou acima da desejada — não há necessidade de calagem.'};
  var nc=(V2-ind.V)*ind.T/(10*PRNT);
  /* A fórmula é para 0-20 cm. Outra profundidade escala proporcionalmente — e o
     ajuste vai dito na trilha, para ninguém aplicar dose de 40 cm achando que é padrão. */
  var prof=Number(profundidadeCm);
  var fator=(isFinite(prof)&&prof>0)?(prof/20):1;
  return {nc:Math.round(nc*fator*100)/100, ncBase:Math.round(nc*100)/100,
          V1:ind.V, V2:V2, T:ind.T, PRNT:PRNT,
          profundidade:(isFinite(prof)&&prof>0)?prof:20, fator:fator};
}

/* A trilha não é enfeite: é o que separa "o Agracta mandou passar 2,3 t/ha" de uma
   conta conferível. Sem ela o número não tem como ser auditado, e num ensaio sob BPL
   número sem origem não vale. */
function soloCalagemTrilha(c){
  if(!c||c.erro) return [];
  var L=[];
  L.push('Método da saturação por bases');
  L.push('NC (t/ha) = (V2 − V1) × T ÷ (10 × PRNT)');
  L.push('V1 (atual) = '+c.V1+'%   ·   V2 (desejada) = '+c.V2+'%');
  L.push('T (CTC a pH 7) = '+c.T+' mmolc/dm³   ·   PRNT = '+c.PRNT+'%');
  if(c.nc===0){ L.push(c.nota||'Sem necessidade de calagem.'); return L; }
  L.push('NC = ('+c.V2+' − '+c.V1+') × '+c.T+' ÷ (10 × '+c.PRNT+') = '+c.ncBase+' t/ha  (0–20 cm)');
  if(c.fator!==1) L.push('Ajuste para '+c.profundidade+' cm: '+c.ncBase+' × '+(Math.round(c.fator*100)/100)+' = '+c.nc+' t/ha');
  return L;
}

/* ----- Análise de solo na ficha da quadra ----- */
var _soloAnEdit=null;   /* id da análise em edição, ou 'nova' */

function soloAnaliseHtml(id){
  var lista=soloAnalises(id), atual=lista[0]||null;
  var h='<div class="solo-sub"><div class="solo-h"><b>ANÁLISE DE SOLO</b>'+
        '<button class="solo-rf" onclick="soloNovaAnalise(\''+esc(id)+'\')">+ Lançar</button></div>';

  if(!lista.length){
    h+='<div class="solo-est">Nenhuma análise lançada. É ela — e não o mapa — que embasa recomendação de adubação.</div>';
    return h+'<div id="soloAnForm" class="solo-form" style="display:none"></div></div>';
  }

  var ind=soloIndices(atual.resultados);
  h+='<div class="solo-meta"><span>Coleta <b>'+esc(_soloDataBR(atual.data))+'</b></span>';
  if(atual.laboratorio) h+='<span>Lab <b>'+esc(atual.laboratorio)+'</b></span>';
  if(atual.profundidade) h+='<span>Prof. <b>'+esc(atual.profundidade)+' cm</b></span>';
  h+='<span class="solo-src ok">laudo</span></div>';

  h+='<div class="solo-grid">';
  SOLO_ANALISE_CAMPOS.forEach(function(c){
    var v=atual.resultados&&atual.resultados[c.k];
    if(v===''||v==null) return;
    h+='<div class="solo-card"><div class="lab">'+esc(c.rot)+'</div><div class="val">'+
       esc(String(v).replace('.',','))+(c.un?' <small>'+esc(c.un)+'</small>':'')+'</div></div>';
  });
  /* Derivados aparecem separados dos medidos: são conta, não leitura de laboratório. */
  [['SB',ind.SB,'mmolc/dm³'],['CTC (T)',ind.T,'mmolc/dm³'],['V%',ind.V,'%'],['m%',ind.m,'%']].forEach(function(x){
    if(x[1]==null) return;
    h+='<div class="solo-card" style="border-style:dashed"><div class="lab">'+esc(x[0])+'</div><div class="val">'+
       esc(String(x[1]).replace('.',','))+' <small>'+esc(x[2])+'</small></div><div class="der">calculado</div></div>';
  });
  h+='</div>';

  h+='<div class="solo-fb" style="margin-top:8px">'+
     '<button class="solo-rf" onclick="soloEditarAnalise(\''+esc(id)+'\',\''+esc(atual.id)+'\')">Editar</button>';
  if(lista.length>1) h+='<button class="solo-rf" onclick="soloHistoricoAnalises(\''+esc(id)+'\')">Histórico ('+lista.length+')</button>';
  h+='</div>';
  h+='<div id="soloAnHist"></div>';
  h+='<div id="soloAnForm" class="solo-form" style="display:none"></div>';
  return h+'</div>';
}

function soloNovaAnalise(id){ _soloAnEdit='nova'; _soloAnFormPinta(id, null); }
function soloEditarAnalise(id, aid){
  var a=soloAnalises(id).filter(function(x){return x.id===aid;})[0]||null;
  _soloAnEdit=aid; _soloAnFormPinta(id, a);
}
function soloCancelarAnalise(){
  _soloAnEdit=null;
  var el=document.getElementById('soloAnForm');
  if(el){ el.style.display='none'; el.innerHTML=''; }
}

function _soloAnFormPinta(id, a){
  var alvo=document.getElementById('soloAnForm'); if(!alvo) return;
  a=a||{};
  var r=a.resultados||{};
  var h='<div class="solo-f"><label>DATA DA COLETA</label><input id="soloAnData" type="date" value="'+esc(a.data||'')+'"></div>'+
        '<div class="solo-f"><label>LABORATÓRIO</label><input id="soloAnLab" type="text" value="'+esc(a.laboratorio||'')+'"></div>'+
        '<div class="solo-f"><label>PROFUNDIDADE (CM)</label><input id="soloAnProf" type="number" step="1" placeholder="20" value="'+esc(a.profundidade||'')+'"></div>'+
        '<div class="solo-grid">';
  SOLO_ANALISE_CAMPOS.forEach(function(c){
    h+='<div class="solo-f" style="margin:0"><label>'+esc(c.rot)+(c.un?' ('+esc(c.un)+')':'')+'</label>'+
       '<input id="soloAn_'+esc(c.k)+'" type="number" step="'+esc(c.passo)+'" inputmode="decimal" value="'+esc(r[c.k]!=null?r[c.k]:'')+'"></div>';
  });
  h+='</div><div class="solo-fb"><button class="solo-ok" onclick="soloSalvarAnalise(\''+esc(id)+'\')">Salvar</button>'+
     '<button class="solo-rf" onclick="soloCancelarAnalise()">Cancelar</button>';
  if(a.id) h+='<button class="solo-rf" onclick="soloApagarAnalise(\''+esc(id)+'\',\''+esc(a.id)+'\')">Apagar</button>';
  h+='</div>';
  alvo.innerHTML=h; alvo.style.display='block';
}

function soloSalvarAnalise(id){
  if(!data[id]) return;
  var dataColeta=_soloVal('soloAnData');
  if(!dataColeta){ alert('Informe a data da coleta — sem ela a análise não entra no histórico nem serve de procedência.'); return; }
  var res={}, algum=false;
  SOLO_ANALISE_CAMPOS.forEach(function(c){
    var v=_soloVal('soloAn_'+c.k);
    if(v!==''){ res[c.k]=Number(v); algum=true; }
  });
  if(!algum){ alert('Preencha ao menos um resultado do laudo.'); return; }

  var lista=((data[id].solo||{}).analises||[]).slice();
  var antiga=lista.filter(function(x){ return x.id===_soloAnEdit; })[0]||null;
  var reg={
    id:(antiga?antiga.id:(typeof uid==='function'?uid():'a'+Date.now())),
    data:dataColeta, laboratorio:_soloVal('soloAnLab'),
    profundidade:(_soloVal('soloAnProf')?Number(_soloVal('soloAnProf')):20),
    resultados:res, fonte:'laudo',
    user:(typeof _currentUserName==='function'?(_currentUserName()||'Não identificado'):'Não identificado'),
    ts:(antiga?antiga.ts:Date.now()), iso:(antiga?antiga.iso:new Date().toISOString()),
    app:(typeof APP_VER!=='undefined'?APP_VER:null)
  };
  if(antiga) reg.revisadoEm=Date.now();
  lista=lista.filter(function(x){ return x.id!==reg.id; });
  lista.push(reg);
  _soloSet(id, {analises:lista});
  soloCancelarAnalise();
  try{ if(typeof _stxToast==='function') _stxToast('Análise salva'); }catch(e){}
  try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}
}

function soloApagarAnalise(id, aid){
  if(!data[id]) return;
  if(!confirm('Apagar esta análise? O histórico dela é perdido.')) return;
  var lista=((data[id].solo||{}).analises||[]).filter(function(x){ return x.id!==aid; });
  _soloSet(id, {analises:lista});
  soloCancelarAnalise();
  try{ if(curV===id && typeof showD==='function') showD(id); }catch(e){}
}

/* Evolução: o valor de hoje só significa alguma coisa comparado com o de antes. */
function soloHistoricoAnalises(id){
  var alvo=document.getElementById('soloAnHist'); if(!alvo) return;
  if(alvo.innerHTML){ alvo.innerHTML=''; return; }
  var lista=soloAnalises(id);
  var h='<div style="margin-top:8px;overflow-x:auto"><table style="border-collapse:collapse;font-size:11px;white-space:nowrap">'+
        '<tr><th style="text-align:left;padding:3px 8px 3px 0;color:var(--gp-text-3,#727c75)">Coleta</th>';
  ['pH','MO','P','K','V%'].forEach(function(t){
    h+='<th style="text-align:right;padding:3px 8px;color:var(--gp-text-3,#727c75)">'+esc(t)+'</th>';
  });
  h+='</tr>';
  lista.forEach(function(a){
    var ind=soloIndices(a.resultados), r=a.resultados||{};
    function cel(v){ return '<td style="text-align:right;padding:3px 8px;color:var(--gp-text,#e9ede9)">'+
      (v==null||v===''?'—':esc(String(v).replace('.',',')))+'</td>'; }
    h+='<tr><td style="padding:3px 8px 3px 0;color:var(--gp-text-2,#a8b3aa)">'+esc(_soloDataBR(a.data))+'</td>'+
       cel(r.pH)+cel(r.MO)+cel(r.P)+cel(r.K)+cel(ind.V)+'</tr>';
  });
  alvo.innerHTML=h+'</table></div>';
}

/* ----- Calagem na ficha ----- */
var _soloCalMostra={};
function soloCalagemHtml(id){
  var a=soloAnaliseAtual(id);
  if(!a) return '';
  var ind=soloIndices(a.resultados);
  var h='<div class="solo-sub"><div class="solo-h"><b>CALAGEM</b></div>';
  if(ind.T==null||ind.V==null){
    return h+'<div class="solo-est">Faltam Ca, Mg, K ou H+Al no laudo para calcular a CTC.</div></div>';
  }
  var cfg=(data[id].solo&&data[id].solo.calagem)||{};
  h+='<div class="solo-grid">'+
     '<div class="solo-f" style="margin:0"><label>V% DESEJADA</label><input id="soloCalV2" type="number" step="1" inputmode="numeric" value="'+esc(cfg.V2!=null?cfg.V2:'')+'" oninput="soloCalcular(\''+esc(id)+'\')"></div>'+
     '<div class="solo-f" style="margin:0"><label>PRNT (%)</label><input id="soloCalPrnt" type="number" step="1" inputmode="numeric" value="'+esc(cfg.PRNT!=null?cfg.PRNT:'')+'" oninput="soloCalcular(\''+esc(id)+'\')"></div>'+
     '</div>';
  h+='<div id="soloCalOut">'+soloCalagemSaidaHtml(id)+'</div>';
  /* O V2 vem da tabela da cultura, que é conteúdo de publicação. Pedir em vez de
     embutir mantém o cálculo funcionando sem depender de nenhuma obra — e quem tem
     a tabela licenciada usa o valor dela. */
  h+='<div class="solo-est" style="margin-top:6px">A saturação desejada (V2) depende da cultura e vem da tabela de recomendação que você usa.</div>';
  return h+'</div>';
}

function soloCalagemSaidaHtml(id){
  var a=soloAnaliseAtual(id); if(!a) return '';
  var cfg=(data[id].solo&&data[id].solo.calagem)||{};
  if(cfg.V2==null||cfg.PRNT==null) return '<div class="solo-est">Informe V2 e PRNT para calcular.</div>';
  var c=soloCalagem(a.resultados, cfg.V2, cfg.PRNT, a.profundidade);
  if(c.erro) return '<div class="solo-est">'+esc(c.erro)+'</div>';
  var h='<div class="solo-cl" style="margin-top:6px"><span class="solo-dot" style="background:#8a7f6a"></span>'+
        (c.nc>0?('Calcário: <b>'+String(c.nc).replace('.',',')+' t/ha</b>'):'Sem necessidade de calagem')+'</div>';
  if(c.nota) h+='<div class="solo-est">'+esc(c.nota)+'</div>';
  h+='<div class="solo-fb" style="margin-top:6px"><button class="solo-rf" onclick="soloToggleCalculo(\''+esc(id)+'\')">'+
     (_soloCalMostra[id]?'Ocultar cálculo':'Mostrar cálculo')+'</button></div>';
  if(_soloCalMostra[id]){
    h+='<div class="solo-av mix" style="font-family:ui-monospace,monospace;font-size:10.5px;line-height:1.6">'+
       soloCalagemTrilha(c).map(function(l){ return esc(l); }).join('<br>')+'</div>';
  }
  return h;
}

function soloCalcular(id){
  if(!data[id]) return;
  var v2=_soloVal('soloCalV2'), prnt=_soloVal('soloCalPrnt');
  var cfg={V2:(v2!==''?Number(v2):null), PRNT:(prnt!==''?Number(prnt):null)};
  _soloSet(id, {calagem:cfg});
  var out=document.getElementById('soloCalOut');
  if(out) out.innerHTML=soloCalagemSaidaHtml(id);
}
function soloToggleCalculo(id){
  _soloCalMostra[id]=!_soloCalMostra[id];
  var out=document.getElementById('soloCalOut');
  if(out) out.innerHTML=soloCalagemSaidaHtml(id);
}

/* ----- Pacote de tabelas de recomendação -----
   O motor é do Agracta; as TABELAS não. Elas ficam num arquivo separado que o app
   carrega e que nunca é versionado — exatamente como ndvi-credenciais.json e
   ecowitt-credenciais.json já fazem neste projeto.

   A razão é concreta, não jurídica: este repositório é PÚBLICO e o site sai dele.
   Tabela colada dentro do app.js seria publicada para o mundo junto com o código.
   Num arquivo à parte, fora do versionamento, o exemplar comprado continua sendo
   uso pessoal de quem o comprou.

   Efeito colateral bom: trocando o pacote, o mesmo motor atende CQFS-RS/SC ou a 5ª
   Aproximação de Minas, em vez de assumir São Paulo como universal. */
var SOLO_PACOTE_KEY='agracta-solo-tabelas-v1';
var _soloPacote=null;

function soloPacote(){
  if(_soloPacote) return _soloPacote;
  try{
    var t=localStorage.getItem(SOLO_PACOTE_KEY);
    if(t) _soloPacote=JSON.parse(t);
  }catch(e){ _soloPacote=null; }
  return _soloPacote;
}
function soloPacoteNome(){ var p=soloPacote(); return p?(p.nome||'pacote sem nome'):null; }

/* Valida antes de aceitar: pacote malformado que entra em silêncio vira
   recomendação errada, que é pior que recomendação nenhuma. */
function soloPacoteValidar(obj){
  if(!obj||typeof obj!=='object') return 'Arquivo não é um pacote de tabelas.';
  if(!Array.isArray(obj.culturas)||!obj.culturas.length) return 'O pacote não traz nenhuma cultura.';
  for(var i=0;i<obj.culturas.length;i++){
    var c=obj.culturas[i];
    if(!c||!c.nome) return 'Cultura sem nome na posição '+(i+1)+'.';
    if(c.V2!=null&&(!isFinite(Number(c.V2))||Number(c.V2)<=0||Number(c.V2)>100))
      return 'V2 inválido em "'+c.nome+'" (esperado 1 a 100).';
  }
  return null;
}
function soloPacoteCarregar(texto){
  var obj;
  try{ obj=JSON.parse(texto); }catch(e){ return 'Não consegui ler o arquivo como JSON: '+(e&&e.message||e); }
  var erro=soloPacoteValidar(obj);
  if(erro) return erro;
  _soloPacote=obj;
  try{ localStorage.setItem(SOLO_PACOTE_KEY, JSON.stringify(obj)); }catch(e){
    return 'O pacote é válido, mas não coube no armazenamento deste aparelho.';
  }
  return null;
}
function soloPacoteRemover(){
  _soloPacote=null;
  try{ localStorage.removeItem(SOLO_PACOTE_KEY); }catch(e){}
}
function soloPacoteCulturas(){
  var p=soloPacote(); if(!p) return [];
  return p.culturas.map(function(c){
    return {nome:c.nome, finalidade:c.finalidade||'', rotulo:c.nome+(c.finalidade?' · '+c.finalidade:'')};
  });
}
function _soloPacoteCultura(nome, finalidade){
  return _nucleoNutricao().culturaDoPacote(soloPacote(), nome, finalidade);
}

/* ----- Motor de recomendação -----
   Classifica o teor do laudo na faixa da tabela, escolhe a dose pela produtividade
   esperada e devolve TUDO com a trilha: qual faixa, por que, qual linha da tabela.
   Sem a trilha o número não é conferível, e num ensaio sob BPL isso não vale. */

/* Faixa: a primeira cujo 'ate' cobre o valor. A última pode vir sem 'ate' — é o
   "acima de tudo". */
function _soloFaixa(faixas, valor){
  if(!Array.isArray(faixas)||valor==null||!isFinite(valor)) return null;
  for(var i=0;i<faixas.length;i++){
    var f=faixas[i];
    if(f.ate==null) return f;
    if(valor<=Number(f.ate)) return f;
  }
  return faixas[faixas.length-1]||null;
}
/* Dose: a linha da menor produtividade que ATENDE a esperada. Acima da última
   linha da tabela, usa a última — e a trilha diz que extrapolou, porque
   extrapolar tabela de adubação em silêncio é o tipo de coisa que vira erro caro. */
function _soloDose(linhas, produtividade){
  if(!Array.isArray(linhas)||!linhas.length) return null;
  /* null e '' viram 0 no Number(), e 0 é finito: sem esta guarda, "não informei a
     produtividade" passaria como "produtividade zero" e pegaria calada a menor dose
     da tabela, sem avisar ninguém. */
  var alvo=(produtividade===''||produtividade==null)?NaN:Number(produtividade);
  if(!isFinite(alvo)||alvo<=0) return {dose:linhas[0].dose, linha:linhas[0], semProdutividade:true};
  var ordenadas=linhas.slice().sort(function(a,b){ return Number(a.produtividade)-Number(b.produtividade); });
  for(var i=0;i<ordenadas.length;i++){
    if(alvo<=Number(ordenadas[i].produtividade)) return {dose:ordenadas[i].dose, linha:ordenadas[i]};
  }
  var ult=ordenadas[ordenadas.length-1];
  return {dose:ult.dose, linha:ult, extrapolou:true};
}

function soloRecomendar(analise, cultura, finalidade, produtividade){
  var pac=soloPacote();
  if(!pac) return {erro:'Nenhum pacote de tabelas carregado.'};
  var c=_soloPacoteCultura(cultura, finalidade);
  if(!c) return {erro:'A cultura "'+cultura+'" não está no pacote carregado.'};
  if(!analise||!analise.resultados) return {erro:'Sem análise de solo lançada.'};

  var r=analise.resultados, out={cultura:c.nome, finalidade:c.finalidade||'', 
        produtividade:produtividade, pacote:(pac.nome||''), fonte:(pac.fonte||''),
        itens:[], trilha:[], V2:(c.V2!=null?Number(c.V2):null)};

  out.trilha.push('Pacote: '+(pac.nome||'sem nome')+(pac.versao?(' ('+pac.versao+')'):''));
  out.trilha.push('Cultura: '+c.nome+(c.finalidade?(' · '+c.finalidade):''));
  if(produtividade!=null&&produtividade!=='') out.trilha.push('Produtividade esperada: '+produtividade+' '+(c.unidadeProdutividade||'t/ha'));

  /* Nitrogênio: não sai da análise de solo. Vem de produtividade esperada e do
     histórico — por isso é tratado à parte, e a trilha diz isso em voz alta. */
  if(c.N){
    var linhasN=c.N.cobertura||[];
    var dN=_soloDose(linhasN, produtividade);
    var totalN=(Number(c.N.plantio)||0)+(dN?Number(dN.dose)||0:0);
    if(totalN>0){
      out.itens.push({nutriente:'N', dose:totalN, unidade:(c.N.unidade||'kg/ha'),
                      detalhe:(c.N.plantio?('plantio '+c.N.plantio+' + cobertura '+(dN?dN.dose:0)):null)});
      out.trilha.push('N — não é estimado pela análise de solo; vem da produtividade esperada e do histórico da gleba.');
      if(c.N.plantio) out.trilha.push('   plantio '+c.N.plantio+' + cobertura '+(dN?dN.dose:0)+' = '+totalN+' kg/ha de N');
      if(dN&&dN.extrapolou) out.trilha.push('   ATENÇÃO: produtividade acima da última linha da tabela — dose extrapolada.');
    }
  }

  /* P e K saem do teor medido, classificado na faixa da tabela. */
  [['P2O5','P'],['K2O','K']].forEach(function(par){
    var chave=par[0], bloco=c[chave];
    if(!bloco) return;
    var criterio=bloco.criterio||par[1];
    var valor=(r[criterio]!=null&&r[criterio]!=='')?Number(r[criterio]):null;
    if(valor==null){
      out.trilha.push(chave+' — sem '+criterio+' no laudo; não calculado.');
      return;
    }
    var f=_soloFaixa(bloco.faixas, valor);
    if(!f){ out.trilha.push(chave+' — o teor de '+criterio+' não caiu em nenhuma faixa da tabela.'); return; }
    var d=_soloDose(f.doses, produtividade);
    if(!d){ out.trilha.push(chave+' — a faixa "'+(f.classe||'')+'" não traz dose.'); return; }
    out.itens.push({nutriente:chave, dose:Number(d.dose), unidade:(bloco.unidade||'kg/ha'),
                    classe:(f.classe||null), teor:valor, criterio:criterio});
    out.trilha.push(chave+' — '+criterio+' medido '+valor+' → classe "'+(f.classe||'—')+'"'+
                    (f.ate!=null?(' (até '+f.ate+')'):' (acima da última faixa)')+
                    ' → '+d.dose+' '+(bloco.unidade||'kg/ha'));
    if(d.extrapolou) out.trilha.push('   ATENÇÃO: produtividade acima da última linha — dose extrapolada.');
    if(d.semProdutividade) out.trilha.push('   Sem produtividade esperada informada: usada a primeira linha da tabela.');
  });

  /* Micronutrientes: aplicam quando o teor está ABAIXO do limite da tabela. */
  (c.micro||[]).forEach(function(mi){
    var crit=mi.criterio||mi.nutriente;
    var valor=(r[crit]!=null&&r[crit]!=='')?Number(r[crit]):null;
    if(valor==null) return;
    if(valor<Number(mi.abaixoDe)){
      out.itens.push({nutriente:mi.nutriente, dose:Number(mi.dose), unidade:(mi.unidade||'kg/ha'), micro:true});
      out.trilha.push(mi.nutriente+' — teor '+valor+' abaixo de '+mi.abaixoDe+' → '+mi.dose+' '+(mi.unidade||'kg/ha'));
    }else{
      out.trilha.push(mi.nutriente+' — teor '+valor+' suficiente (limite '+mi.abaixoDe+'); sem aplicação.');
    }
  });

  if(out.V2!=null) out.trilha.push('V% desejada para esta cultura, segundo o pacote: '+out.V2+'%');
  return out;
}

/* ----- Recomendação na ficha da quadra ----- */
var _soloRecMostra={};

function soloRecomendacaoHtml(id){
  var a=soloAnaliseAtual(id);
  var h='<div class="solo-sub"><div class="solo-h"><b>RECOMENDAÇÃO</b>'+
        '<button class="solo-rf" onclick="soloAbrirPacote()">'+(soloPacote()?'Trocar tabelas':'Carregar tabelas')+'</button></div>';

  if(!soloPacote()){
    h+='<div class="solo-est">Nenhum pacote de tabelas carregado. O Agracta traz o motor; as tabelas de recomendação ficam num arquivo seu, fora do repositório.</div>';
    return h+'<div id="soloPacForm" class="solo-form" style="display:none"></div></div>';
  }
  if(!a){
    h+='<div class="solo-est">Lance uma análise de solo — é ela que embasa a recomendação, não o mapa.</div>';
    return h+'<div id="soloPacForm" class="solo-form" style="display:none"></div></div>';
  }

  var cfg=(data[id].solo&&data[id].solo.rec)||{};
  var culturas=soloPacoteCulturas();
  var opts='<option value="">—</option>'+culturas.map(function(c){
    var v=c.nome+'|'+c.finalidade;
    return '<option value="'+esc(v)+'"'+(cfg.chave===v?' selected':'')+'>'+esc(c.rotulo)+'</option>';
  }).join('');

  h+='<div class="solo-grid">'+
     '<div class="solo-f" style="margin:0"><label>CULTURA</label><select id="soloRecCult" onchange="soloRecalcular(\''+esc(id)+'\')">'+opts+'</select></div>'+
     '<div class="solo-f" style="margin:0"><label>PRODUTIVIDADE ESPERADA</label><input id="soloRecProd" type="number" step="0.5" inputmode="decimal" value="'+esc(cfg.produtividade!=null?cfg.produtividade:'')+'" oninput="soloRecalcular(\''+esc(id)+'\')"></div>'+
     '</div>';
  h+='<div id="soloRecOut">'+soloRecSaidaHtml(id)+'</div>';
  h+='<div class="solo-meta" style="margin-top:6px"><span>Tabelas <b>'+esc(soloPacoteNome())+'</b></span></div>';
  h+='<div id="soloPacForm" class="solo-form" style="display:none"></div>';
  return h+'</div>';
}

function soloRecSaidaHtml(id){
  var cfg=(data[id].solo&&data[id].solo.rec)||{};
  if(!cfg.chave) return '<div class="solo-est">Escolha a cultura para calcular.</div>';
  var partes=String(cfg.chave).split('|');
  var rec=soloRecomendar(soloAnaliseAtual(id), partes[0], partes[1], cfg.produtividade);
  if(rec.erro) return '<div class="solo-est">'+esc(rec.erro)+'</div>';
  var h='';
  if(rec.itens.length){
    h+='<div class="solo-grid">';
    rec.itens.forEach(function(it){
      h+='<div class="solo-card"><div class="lab">'+esc(it.nutriente)+
         (it.classe?' <span style="opacity:.7">'+esc(it.classe)+'</span>':'')+'</div>'+
         '<div class="val">'+esc(String(it.dose).replace('.',','))+' <small>'+esc(it.unidade)+'</small></div>'+
         (it.detalhe?'<div class="der">'+esc(it.detalhe)+'</div>':'')+'</div>';
    });
    h+='</div>';
  }else{
    h+='<div class="solo-est">A tabela não devolveu dose para esta combinação.</div>';
  }
  h+='<div class="solo-fb" style="margin-top:6px"><button class="solo-rf" onclick="soloToggleRec(\''+esc(id)+'\')">'+
     (_soloRecMostra[id]?'Ocultar cálculo':'Mostrar cálculo')+'</button></div>';
  if(_soloRecMostra[id]){
    h+='<div class="solo-av mix" style="font-family:ui-monospace,monospace;font-size:10.5px;line-height:1.6">'+
       rec.trilha.map(function(l){ return esc(l); }).join('<br>')+'</div>';
  }
  /* Recomendação de tabela não é ordem de serviço: a tabela é média regional, e a
     área tem histórico que ela não conhece. */
  h+='<div class="solo-av grossa">⚠ Recomendação calculada a partir do pacote de tabelas e da análise informada. '+
     'Confira contra o histórico da área antes de aplicar.</div>';
  return h;
}

function soloRecalcular(id){
  if(!data[id]) return;
  var el=document.getElementById('soloRecCult');
  var prod=_soloVal('soloRecProd');
  var cfg={chave:(el?el.value:''), produtividade:(prod!==''?Number(prod):null)};
  _soloSet(id, {rec:cfg});

  /* O V2 da cultura vem do pacote: escolher a cultura já preenche a calagem. É o
     que torna a coisa automática — sem isso o número teria de ser copiado à mão da
     tabela para o campo, que é justamente o passo que se queria eliminar. */
  if(cfg.chave){
    var partes=String(cfg.chave).split('|');
    var c=_soloPacoteCultura(partes[0], partes[1]);
    if(c&&c.V2!=null){
      var cal=(data[id].solo&&data[id].solo.calagem)||{};
      if(cal.V2!==Number(c.V2)){
        cal.V2=Number(c.V2);
        cal.V2De=(soloPacoteNome()||'pacote');   /* de onde veio, para a trilha */
        _soloSet(id, {calagem:cal});
        var elV2=document.getElementById('soloCalV2'); if(elV2) elV2.value=c.V2;
        var outCal=document.getElementById('soloCalOut'); if(outCal) outCal.innerHTML=soloCalagemSaidaHtml(id);
      }
    }
  }
  var out=document.getElementById('soloRecOut');
  if(out) out.innerHTML=soloRecSaidaHtml(id);
}
function soloToggleRec(id){
  _soloRecMostra[id]=!_soloRecMostra[id];
  var out=document.getElementById('soloRecOut');
  if(out) out.innerHTML=soloRecSaidaHtml(id);
}

/* Carregar o pacote: arquivo ou colar. Nada vai para o repositório. */
function soloAbrirPacote(){
  var alvo=document.getElementById('soloPacForm'); if(!alvo) return;
  if(alvo.style.display==='block'){ alvo.style.display='none'; alvo.innerHTML=''; return; }
  alvo.innerHTML=
    '<div class="solo-f"><label>ARQUIVO DE TABELAS (.json)</label>'+
    '<input id="soloPacFile" type="file" accept=".json,application/json" onchange="soloPacoteDoArquivo(this)"></div>'+
    '<div class="solo-f"><label>OU COLE O CONTEÚDO</label>'+
    '<input id="soloPacTexto" type="text" placeholder=\'{"nome":"...","culturas":[...]}\'></div>'+
    '<div class="solo-fb"><button class="solo-ok" onclick="soloPacoteDoTexto()">Carregar</button>'+
    '<button class="solo-rf" onclick="soloAbrirPacote()">Fechar</button>'+
    (soloPacote()?'<button class="solo-rf" onclick="soloPacoteApagar()">Remover</button>':'')+'</div>'+
    '<div class="solo-est" style="margin-top:6px">O pacote fica só neste aparelho. Não é enviado nem versionado.</div>';
  alvo.style.display='block';
}
function soloPacoteDoArquivo(input){
  var f=input&&input.files&&input.files[0]; if(!f) return;
  var fr=new FileReader();
  fr.onload=function(){ _soloPacoteAplica(String(fr.result||'')); };
  fr.onerror=function(){ alert('Não consegui ler o arquivo.'); };
  fr.readAsText(f);
}
function soloPacoteDoTexto(){ _soloPacoteAplica(_soloVal('soloPacTexto')); }
function _soloPacoteAplica(texto){
  if(!texto){ alert('Escolha um arquivo ou cole o conteúdo.'); return; }
  var erro=soloPacoteCarregar(texto);
  if(erro){ alert(erro); return; }
  try{ if(typeof _stxToast==='function') _stxToast('Tabelas carregadas: '+soloPacoteNome()); }catch(e){}
  try{ if(curV && typeof showD==='function') showD(curV); }catch(e){}
}
function soloPacoteApagar(){
  if(!confirm('Remover o pacote de tabelas deste aparelho?')) return;
  soloPacoteRemover();
  try{ if(curV && typeof showD==='function') showD(curV); }catch(e){}
}

/* ----- Camada Solo no mapa -----
   Desenhada como IMAGEM sobre o mapa, e não como tile, pelo mesmo motivo do NDVI:
   para recortar pelas quadras é preciso ler os pixels num canvas, e canvas que
   recebeu imagem de outro domínio fica "sujo" — o navegador proíbe exportá-lo.
   Vindo pelo proxy a imagem é mesma-origem e o recorte funciona.

   O mapa inteiro é a leitura padrão. O recorte pelas quadras é uma escolha de
   visualização e não pode ligar sozinho: do contrário a pessoa pede "mapa de
   solos" e recebe somente manchas dentro dos polígonos, como se não existisse
   levantamento ao redor. A preferência fica neste aparelho. */
var SOLO_RECORTE_PREF_KEY='agracta-solo-recorte';
function _soloRecorteInicial(){
  try{ return localStorage.getItem(SOLO_RECORTE_PREF_KEY)==='1'; }catch(e){ return false; }
}
var _soloLayer=null, _soloRecorte=_soloRecorteInicial(), _soloOpacidade=0.55, _soloMapaLigada=false;
var _soloMapaSeq=0, _soloObjURL=null, _soloMoveT=null, _soloCamadaMapa=null;

function soloLayerAtiva(){ return !!_soloMapaLigada; }
function soloRecorteAtivo(){ return !!_soloRecorte; }

function toggleSoloLayer(){
  if(!_map) initMap();
  soloBindMove();
  if(_soloMapaLigada){
    soloLimpar();
    try{ if(typeof _stxToast==='function') _stxToast('Camada de solo desligada'); }catch(e){}
  }else soloCarregarMapa(false);
  return !!_soloMapaLigada;
}

function soloLimpar(){
  _soloMapaLigada=false;
  _soloMapaSeq++;
  if(_soloLayer){ try{ _map.removeLayer(_soloLayer); }catch(e){} _soloLayer=null; }
  if(_soloObjURL){ try{ URL.revokeObjectURL(_soloObjURL); }catch(e){} _soloObjURL=null; }
  _soloCamadaMapa=null;
  try{ soloMapaLegendaEsconder(); }catch(e){}
  try{ if(typeof sincronizarGavetaSolo==='function') sincronizarGavetaSolo(); }catch(e){}
}

/* Liga/desliga o recorte. Se a camada está no mapa, redesenha na hora. */
function soloSetRecorte(v){
  _soloRecorte=!!v;
  try{ localStorage.setItem(SOLO_RECORTE_PREF_KEY,_soloRecorte?'1':'0'); }catch(e){}
  if(_soloMapaLigada) soloCarregarMapa(true);
}
function soloSetOpacidade(v){
  _soloOpacidade=parseFloat(v);
  if(_soloLayer) _soloLayer.setOpacity(_soloOpacidade);
}

function _soloMapaFalhou(msg,seq){
  if(seq!==_soloMapaSeq)return;
  if(!_soloLayer){_soloMapaLigada=false;try{soloMapaLegendaEsconder();}catch(e){}}
  try{ if(typeof sincronizarGavetaSolo==='function') sincronizarGavetaSolo(); }catch(e){}
  try{ if(typeof _stxToast==='function') _stxToast('Solo: '+msg); }catch(e){}
}
function _soloMapaLegendaCss(){
  if(document.getElementById('soloMapaLegendaCss'))return;
  var s=document.createElement('style');s.id='soloMapaLegendaCss';
  s.textContent='.solo-map-legend{position:fixed;right:12px;bottom:82px;z-index:880;width:min(270px,72vw);border:1px solid rgba(255,255,255,.18);border-radius:12px;background:rgba(15,21,18,.94);color:#e8efe9;box-shadow:0 10px 32px rgba(0,0,0,.42);font:600 11px/1.35 system-ui,sans-serif;overflow:hidden;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}'+
   '.solo-map-legend button{width:100%;display:flex;align-items:center;justify-content:space-between;gap:8px;border:0;background:transparent;color:inherit;padding:9px 11px;font:800 11px system-ui;cursor:pointer;text-align:left}.solo-map-legend button small{font-size:9px;color:#9eaaa2;font-weight:650}'+
   '.solo-map-legend-body{max-height:38vh;overflow:auto;padding:0 8px 8px;background:#fff}.solo-map-legend-body img{display:block;width:100%;height:auto}.solo-map-legend.collapsed .solo-map-legend-body{display:none}@media(max-width:620px){.solo-map-legend{right:8px;bottom:76px;width:min(230px,68vw)}}';
  document.head.appendChild(s);
}
function soloMapaLegendaAlternar(){var el=document.getElementById('soloMapaLegenda');if(el)el.classList.toggle('collapsed');}
function soloMapaLegendaEsconder(){var el=document.getElementById('soloMapaLegenda');if(el)el.remove();}
function soloMapaLegendaMostrar(camada){
  if(!camada)return;
  _soloMapaLegendaCss();
  var el=document.getElementById('soloMapaLegenda');
  /* Na primeira abertura a legenda aparece de verdade. Depois o usuário pode
     recolhê-la; recargas ao mover o mapa preservam o estado escolhido. */
  if(!el){el=document.createElement('aside');el.id='soloMapaLegenda';el.className='solo-map-legend';document.body.appendChild(el);}
  var src=SOLO_PROXY+'/solo/legenda?camada='+encodeURIComponent(camada);
  el.innerHTML='<button type="button" onclick="soloMapaLegendaAlternar()"><span>Legenda do solo</span><small>Embrapa · abrir/fechar</small></button><div class="solo-map-legend-body"><img src="'+esc(src)+'" alt="Legenda oficial da camada pedológica da Embrapa"></div>';
}

function soloCarregarMapa(silencioso){
  if(!_map) initMap();
  _soloMapaLigada=true;
  try{ if(typeof sincronizarGavetaSolo==='function') sincronizarGavetaSolo(); }catch(e){}
  if(!silencioso){try{if(typeof _stxToast==='function')_stxToast('Carregando mapa de solos…');}catch(e){}}
  var bb=ndviBBox(), w=bb[0], s=bb[1], e=bb[2], n=bb[3];
  var seq=++_soloMapaSeq;
  fetch(SOLO_PROXY+'/solo/mapa?bbox='+bb.join(',')+'&width='+ndviPx(bb))
    .then(function(r){
      if(r.ok){
        try{_soloCamadaMapa=r.headers&&r.headers.get?r.headers.get('X-Solo-Camada'):null;}catch(e){_soloCamadaMapa=null;}
        return r.blob();
      }
      return r.json().then(function(j){ throw new Error(j.error||('o servidor respondeu '+r.status)); });
    })
    .then(function(blob){
      if(seq!==_soloMapaSeq) return;               /* já pediram outro pedaço do mapa */
      var bu=URL.createObjectURL(blob), img=new Image();
      img.onerror=function(){
        try{ URL.revokeObjectURL(bu); }catch(er){}
        _soloMapaFalhou('não consegui ler a imagem do mapa.',seq);
      };
      img.onload=function(){
        if(seq!==_soloMapaSeq||!_soloMapaLigada){ try{ URL.revokeObjectURL(bu); }catch(er){} return; }
        var iw=img.naturalWidth||1024, ih=img.naturalHeight||1024, url=bu;
        if(_soloRecorte){
          try{
            var cv=document.createElement('canvas'); cv.width=iw; cv.height=ih;
            var ctx=cv.getContext('2d'); ctx.beginPath();
            var houve=false;
            quadrasAtivas().forEach(function(id){
              var pp=QGEO[id]; if(!pp||pp.length<3) return;
              houve=true;
              pp.forEach(function(pt,i){
                var px=(pt[1]-w)/(e-w)*iw, py=(n-pt[0])/(n-s)*ih;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
              });
              ctx.closePath();
            });
            /* Sem quadra nenhuma o clip vazio apagaria a imagem inteira e pareceria
               que a consulta falhou. Melhor mostrar o mapa inteiro. */
            if(houve){ ctx.clip(); ctx.drawImage(img,0,0); url=cv.toDataURL('image/png'); }
          }catch(err){ url=bu; }
        }
        if(_soloLayer){ try{ _map.removeLayer(_soloLayer); }catch(er){} }
        if(_soloObjURL){ try{ URL.revokeObjectURL(_soloObjURL); }catch(er){} _soloObjURL=null; }
        _soloLayer=LF.imageOverlay(url,[[s,w],[n,e]],{opacity:_soloOpacidade,
                     attribution:'Solos © Embrapa GeoInfo'}).addTo(_map);
        _soloLayer.bringToFront();
        if(url===bu) _soloObjURL=bu; else { try{ URL.revokeObjectURL(bu); }catch(er){} }
        try{ soloMapaLegendaMostrar(_soloCamadaMapa); }catch(er){}
        if(!silencioso){try{if(typeof _stxToast==='function')_stxToast('Camada de solo ligada');}catch(er){}}
        try{ if(typeof sincronizarGavetaSolo==='function') sincronizarGavetaSolo(); }catch(er){}
      };
      img.src=bu;
    })
    .catch(function(err){
      if(seq!==_soloMapaSeq) return;
      _soloMapaFalhou((err&&err.message)||String(err),seq);
    });
}

/* Recarrega ao mover o mapa, como o NDVI faz — a imagem cobre só o que está
   visível, então sem isto ela ficaria "presa" no enquadramento antigo. */
function soloOnMove(){
  if(!_soloMapaLigada||!_soloLayer) return;
  clearTimeout(_soloMoveT);
  _soloMoveT=setTimeout(function(){ if(_soloMapaLigada) soloCarregarMapa(true); }, 700);
}
/* Amarra uma vez só, no mesmo molde do NDVI — sem a trava, cada abertura da
   camada empilharia mais um ouvinte e o mapa recarregaria N vezes por arrasto. */
function soloBindMove(){
  if(_map && !_map.__soloMove){ _map.__soloMove=true; _map.on('moveend', soloOnMove); }
}

/* Fallback triplo: garante init() mesmo se img.onload nao disparar */
if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',function(){setTimeout(init,100)});
}else{
  setTimeout(init,50);
}
window.addEventListener('load',function(){setTimeout(init,100)});
setInterval(function(){try{if(editMode||drawMode||_grOn)return;render();updateAgendaBadge();if(typeof updateTodayBadge==='function')updateTodayBadge();if(agO)renderAgenda();}catch(e){}},60000);
